INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1150064100', 260, 'Banghwa 3-dong', '방화3동', 'Gangseo-gu', '강서구', 'M193.9,411.81 L184.5,417.98 L176.16,427.38 L173.15,432.64 L171.12,433.39 L168.34,435.65 L162.7,442.64 L161.42,449.34 L161.95,453.93 L164.9,456.55 L148.95,456.08 L149.11,450.18 L146.9,449.97 L126.32,449.04 L123.3,450.53 L122.69,452.69 L116.4,453.52 L112.97,453.3 L113.15,451.82 L116.38,442.42 L118.71,439.71 L119.61,433.92 L117.51,433.7 L119.58,429.81 L120.29,427.68 L120.07,424.9 L124.28,423.84 L125.8,421.15 L127.81,419.03 L132.4,419.63 L136.23,421.74 L138.94,418.65 L141.12,419.93 L142.62,423.17 L144.05,417.83 L144.8,412.94 L144.73,411.21 L142.25,409.93 L143.67,407.98 L142.7,407.15 L155.4,383.38 L172.32,398.58 L178.86,403.69 L193.9,411.81 Z', 'held', '["arc"]', 'The creative maintenance team at the Gangseo Technical High School workspace takes orders for household tools and vehicle parts together, but skilled labor is limited.', '강서공업고등학교 작업 공간의 창작 정비조는 생활 공구와 차량용 부품 주문을 함께 받지만 숙련 인력은 한정돼 있다.', 'The residents of Banghwa 3-dong negotiate the cost of their next choice: securing workbenches for household tools.', '방화3동 주민들은 다음 선택의 비용을 협의한다: 생활 공구용 작업대를 확보한다.', 1, 2552797.929997004, 2486.330753177729);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153051000', 261, 'Sindorim-dong', '신도림동', 'Guro-gu', '구로구', 'M372.67,692.42 L368.97,694.82 L362,694.65 L360.94,693.34 L357.91,692.29 L344.84,701.81 L337.52,708.01 L334.82,708.62 L334.12,708.37 L332.7,707.13 L329.58,703.74 L324.65,703.73 L320.68,701.64 L310.58,690.68 L324.99,670.04 L327.96,661.1 L334.42,664.59 L356.96,678.16 L359.95,680.89 L362.99,686.18 L366.48,687.67 L372.67,692.42 Z', 'held', '["free-city"]', 'The creative operations team at the Sindorim transfer space must decide whether to repair broken carrying equipment in the passage or move it to a space set aside out of the way.', '신도림 환승 공간의 창작 운영조는 고장 난 운반 장비를 통로에서 수리할지 비켜 둔 공간으로 옮길지 결정해야 한다.', 'The residents of Sindorim-dong negotiate the cost of their next choice: moving the maintenance area out of the passage.', '신도림동 주민들은 다음 선택의 비용을 협의한다: 정비 구획을 통로 밖으로 옮긴다.', 3, 1375464.764538088, 7790.384949336358);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153052000', 262, 'Guro 1-dong', '구로1동', 'Guro-gu', '구로구', 'M330.63,772 L323.3,770.79 L318.24,773.23 L313.65,774 L314.85,770.04 L315.28,762.67 L308.1,761.65 L300.34,750.39 L299.22,748.22 L299.13,745.04 L297.15,738.91 L295.42,738.89 L294.67,731.83 L295.76,734.07 L303.78,732.25 L309.87,728.59 L324.33,722.14 L329.54,721.19 L328.22,725.61 L327.78,731.14 L328.91,748.43 L328.35,752.71 L328.82,762.85 L329.16,766.84 L330.63,772 Z', 'held', '["free-city"]', 'The residents around the space recorded as a retention basin discuss drainage inspection and securing living passages together, but they do not immediately use the standing water as household water.', '유수지로 기록된 공간 주변 주민들은 배수 점검과 생활 통로 확보를 함께 논의하지만 고인 물을 곧바로 생활수로 쓰지는 않는다.', 'The residents of Guro 1-dong negotiate the cost of their next choice: inspecting the inlet and the detour walkway section together.', '구로1동 주민들은 다음 선택의 비용을 협의한다: 유입구와 우회 보행 구간을 함께 점검한다.', 1, 1082490.8651219665, 5546.651887287284);
