INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153054000', 264, 'Guro 3-dong', '구로3동', 'Guro-gu', '구로구', 'M384.44,792.6 L382.93,797.6 L374.93,798.99 L374.6,798.15 L369.85,793.02 L367.25,792.81 L363.35,791.37 L361.17,781.51 L361.83,780.4 L350.25,776.2 L346.53,775.68 L352.73,766.84 L362.52,758.63 L373.04,750.45 L379.14,766.46 L382.09,769.6 L387.38,773.46 L394,775.87 L395.33,775.96 L384.44,792.6 Z', 'held', '["free-city"]', 'The work crews around the Guro Digital Complex want to change the handover schedule so that commuting workers and parts boxes are not received at the same time.', '구로디지털단지 주변 작업반은 출퇴근 인원과 부품 상자를 같은 시간에 받지 않도록 인계표를 바꾸려 한다.', 'The residents of Guro 3-dong negotiate the cost of their next choice: securing worker transit times first.', '구로3동 주민들은 다음 선택의 비용을 협의한다: 작업자 통과 시간을 먼저 확보한다.', 2, 1042354.39201667, 6514.291158559638);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153055000', 265, 'Guro 4-dong', '구로4동', 'Guro-gu', '구로구', 'M373.04,750.45 L362.52,758.63 L352.73,766.84 L346.53,775.68 L346.08,775.65 L342.58,765.14 L341.56,761.42 L340.52,755.7 L340.86,755.53 L344.67,756.71 L351.74,757.89 L358.76,746.13 L354.25,738.62 L367.8,729.93 L370.65,742.19 L373.04,750.45 Z', 'held', '["free-city"]', 'The residents along the Dorimcheon split the same labor between clearing debris at the water''s edge and repairing interiors. The stream boundary is not a route that can be crossed automatically.', '도림천을 접한 주민들은 물가의 잔해를 치우는 일과 실내 보수에 같은 인력을 나눠 쓴다. 하천 경계는 자동으로 건널 수 있는 길이 아니다.', 'The residents of Guro 4-dong negotiate the cost of their next choice: clearing the debris connected to residential drainage first.', '구로4동 주민들은 다음 선택의 비용을 협의한다: 주거지 배수와 이어진 잔해부터 치운다.', 0, 516118.77206599485, 10193.58388949913);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153056000', 266, 'Guro 5-dong', '구로5동', 'Guro-gu', '구로구', 'M368.41,705.85 L367.58,710.45 L367.27,716.29 L367.8,729.93 L354.25,738.62 L349.72,731.8 L342.51,724.97 L340.48,723.9 L339.18,722.8 L328.63,710.63 L332.7,707.13 L334.12,708.37 L334.82,708.62 L337.52,708.01 L344.84,701.81 L357.91,692.29 L360.94,693.34 L362,694.65 L368.97,694.82 L368.41,705.85 Z', 'held', '["free-city"]', 'The Guro Station handover team wants to make the pickup order and owners public so that no particular work crew takes supplies from outside first.', '구로역 인계조는 외부에서 온 물자를 특정 작업반이 먼저 가져가지 않도록 수령 순서와 소유자를 공개하려 한다.', 'The residents of Guro 5-dong negotiate the cost of their next choice: checking reserved orders and recipients together.', '구로5동 주민들은 다음 선택의 비용을 협의한다: 예약 주문과 수령자를 함께 확인한다.', 1, 1022494.7453295469, 8342.83016021823);
