INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153077000', 273, 'Oryu 1-dong', '오류1동', 'Guro-gu', '구로구', 'M210.79,719.86 L218.28,720.32 L226.26,721.89 L238.34,729.29 L242.84,733.03 L245.14,736.3 L230.16,740.98 L228.77,742.35 L226.01,743.19 L208.7,745.28 L206.69,740.5 L205.36,734.35 L198.31,728.94 L197.9,728.36 L197.5,725.83 L197.84,724.5 L201.04,720.55 L202.03,719.4 L203.55,718.36 L205.47,718.37 L209.69,720.16 L210.79,719.86 Z', 'held', '["free-city"]', 'At Oryu Market, a repairer sets up an inspection table so that usable parts and salvaged metal are not exchanged at the same value.', '오류시장에서는 쓸 수 있는 부품과 회수 금속을 같은 값으로 교환하지 않으려 수리공이 검사대를 마련한다.', 'The residents of Oryu 1-dong negotiate the cost of their next choice: inspecting parts for household equipment first.', '오류1동 주민들은 다음 선택의 비용을 협의한다: 생활 설비용 부품부터 검사한다.', 1, 746743.6133857409, 9250.966297091749);
