INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153079000', 275, 'Sugung-dong', '수궁동', 'Guro-gu', '구로구', 'M204.01,718.29 L202.03,719.4 L197.84,724.5 L197.49,726.66 L198.31,728.94 L205.36,734.35 L206.69,740.5 L208.7,745.28 L192.7,745.48 L192.7,744.99 L191.94,744.95 L176.75,744.89 L176.31,745.08 L176.43,751.9 L176.95,752.08 L175.17,754.15 L168.36,760.52 L165.34,761.84 L164.63,756.41 L157.54,753.26 L152.64,750.33 L150.67,750.55 L145.18,747.46 L144.2,745.13 L140.77,744.66 L140.53,739.5 L136.8,733.51 L139.76,730.26 L140.81,726.25 L143.14,727.23 L145.29,728.71 L146.96,728.09 L151.88,724.27 L153.99,724.98 L156.32,723.08 L155.26,718.49 L157.66,714.62 L161.66,712.91 L161.46,709.4 L164.21,698.48 L163.64,692.98 L175.23,688.93 L175.97,688.95 L187.83,693.26 L187.72,695.91 L193.41,702.45 L198.24,707.03 L202.12,708.43 L203.48,709.69 L204.17,711.79 L204.44,717.14 L204.01,718.29 Z', 'held', '["free-city"]', 'The production team at Yerim Design High School rewrites the old route guidance and wants to make signs that even residents who have difficulty reading can recognize.', '예림디자인고등학교의 제작조는 낡은 길 안내를 다시 쓰며 글을 읽기 어려운 주민도 알아볼 표지를 만들려 한다.', 'The residents of Sugung-dong negotiate the cost of their next choice: cross-checking the on-site residents against the guidance signs.', '수궁동 주민들은 다음 선택의 비용을 협의한다: 현장 주민과 안내 표지를 대조한다.', 1, 2654011.032891268, 2440.3440376599756);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153080000', 276, 'Hang-dong', '항동', 'Guro-gu', '구로구', 'M168.36,760.52 L173.86,762.79 L179.09,763.03 L180.21,765.02 L180.16,767.38 L182.12,771.74 L185.15,772.64 L186.57,776.61 L191.24,778.37 L191.22,782.08 L187.64,788.14 L191.31,789.59 L190.91,792.21 L192.5,795.97 L191.89,798.79 L190.28,801.26 L184.09,804.39 L183.03,805.99 L181.54,806.51 L173.55,803.76 L171.15,804.04 L168.44,806.14 L164,807.25 L161.21,809.22 L159.92,805.8 L154.18,806.1 L153.95,808.47 L154.96,809.86 L151.96,809.62 L152.54,813.37 L150.39,815.75 L150.13,816.89 L148.62,816.79 L148.01,815.29 L146.77,814.11 L143.14,813.76 L141.32,811.37 L141.68,807.37 L142.92,804.97 L145.22,804.03 L145.17,802.58 L148.01,799 L151.3,798.94 L155.28,791.29 L156.35,785.95 L155.02,782.52 L155.03,772.59 L160.39,770.03 L163.36,768.09 L166.67,764.48 L165.41,763.28 L165.34,761.84 L168.36,760.52 Z', 'held', '["free-city"]', 'The creative community in the Hang-dong Elementary School yard repairs carrying equipment and household tools together to keep ground access open. They do not leave living logistics empty just because no station object has been assigned.', '항동초등학교 마당의 창작 공동체는 지상 접근을 유지하기 위해 운반 장비와 가구 공구를 함께 보수한다. 역 객체가 배정되지 않았다는 이유로 생활 물류를 비워 두지 않는다.', 'The residents of Hang-dong negotiate the cost of their next choice: repairing the shared carrying equipment first.', '항동 주민들은 다음 선택의 비용을 협의한다: 공용 운반 장비부터 보수한다.', 0, 1433226.0149478214, 3339.040702644674);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1154551000', 277, 'Gasan-dong', '가산동', 'Geumcheon-gu', '금천구', 'M335.23,775.42 L344.35,783.35 L350.83,791.91 L352.52,793.57 L354.62,795 L358.43,796.34 L371.03,799.11 L374.06,799.33 L375.9,809.08 L368.79,813.47 L368.22,821.72 L362.46,821.41 L348.83,822.3 L354.42,838.42 L355.23,844.93 L347.65,848.76 L330.28,822.83 L324.06,812.52 L318.95,802.19 L316.03,795.26 L311.21,781.36 L311.45,775.18 L313.65,774 L318.24,773.23 L323.3,770.79 L330.63,772 L335.23,775.42 Z', 'held', '["free-city"]', 'The work crews around the Gasan Digital Complex repair pump controllers at the industrial cooperative complex and gather parts at Compuzone Gasan branch. Because the workshop, Bongam Villa, and Onnuri Apartments share power, every increase in night work first cuts the residents'' water supply, which is the opening situation.', '가산디지털단지 주변 작업반은 산업협동화 단지에서 펌프 제어기를 수리하고 컴퓨존 가산점에 부품을 모은다. 작업장과 봉암빌라·온누리아파트가 전력을 나눠 쓰기 때문에 야간 작업을 늘릴 때마다 주민들의 물 공급부터 줄어드는 개막 상황이다.', 'Some of the measuring equipment works, but food and fabric are short, and I Gangmuk''s demand for a night-shift formation has not yet received Council approval.', '계측 설비 일부는 작동하지만 식량과 원단이 부족하며 이강묵의 야간 편성 요구도 아직 평의회 승인을 받지 못한 상태다.', 2, 2242563.537841465, 3429.8693750293887);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1154561000', 278, 'Doksan 1-dong', '독산1동', 'Geumcheon-gu', '금천구', 'M380.06,824.69 L377.9,852.93 L378.15,856.29 L379.96,862.9 L381.88,868 L376.34,869.98 L365.66,875.2 L366.88,880.19 L368.25,884.06 L370.6,888.74 L371.66,891.74 L369.45,892.6 L368.33,892.23 L364.17,894.79 L355.55,893.18 L355.15,891.73 L348.59,881.54 L346.34,879.27 L345.84,877.92 L343.26,865.35 L345.51,863.27 L347.29,862.08 L350.01,861.55 L352.22,862.64 L352.96,862.63 L353.57,862.31 L354.26,860.62 L353,856.73 L347.65,848.76 L355.23,844.93 L354.42,838.42 L348.83,822.3 L362.46,821.41 L368.22,821.72 L368.79,813.47 L375.9,809.08 L374.06,799.33 L382.93,797.6 L380.06,824.69 Z', 'held', '["free-city"]', 'Between Doksan Station and the community center, the people heading to the Gasan workshop and the water-carrying teams from the sloped residential areas use the same alleys. On opening day, the residents are operating a plan to use the first floor of Homeplus Geumcheon Store as a communal cooking and ration space and the Dusan Elementary School playground as a water-container handover point.', '독산역과 주민센터 사이에서는 가산 작업장으로 가는 인원과 사면 주거지의 물 운반조가 같은 골목을 쓴다. 개막일 주민들은 홈플러스금천점 1층을 공동 취사·배급 공간으로, 두산초 운동장을 물통 인계 장소로 사용하는 방안을 운영 중이다.', 'The central contract has expired, so the community center issues temporary shift schedules. The communal kitchen operates only in the morning, the Geumcheon Interchange accepts only light handcarts, and entry of heavily armed formations is on hold.', '중앙 계약의 효력이 끝나 주민센터가 임시 교대표를 발급한다. 공동 취사장은 오전만 운영하고 금천 나들목은 가벼운 손수레만 받으며 중무장 편성의 진입은 보류한 상태다.', 1, 1962963.920287514, 7295.498328824322);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1154562000', 279, 'Doksan 2-dong', '독산2동', 'Geumcheon-gu', '금천구', 'M421.31,845.63 L417.07,847.11 L414.12,845.43 L413.36,845.63 L406.48,849.95 L398.08,857.66 L393.87,857.96 L392.88,859.99 L392.63,863.78 L390.69,867.9 L385.87,872.46 L383.64,873.14 L379.96,862.9 L378.15,856.29 L377.9,852.93 L378.86,842.35 L390.65,842.59 L400.92,840.76 L405.13,839.26 L407.84,839.63 L421.21,844.43 L421.31,845.63 Z', 'held', '["free-city"]', 'The residents of Gungjeon Village and Hojeong Tower carry water containers received on Siheung-daero up the stairs. Water supply to the slope is unstable.', '궁전빌리지와 호정타워 주민들은 시흥대로에서 받은 물통을 계단으로 운반한다. 사면 급수가 불안정한 상황이다.', 'Set a temporary order. Three railings at Gungjeon Village are shaking, but pumping water at the Doksan Elementary School yard can be done only once, in the morning.', '임시 순서를 정한다. 궁전빌리지 난간 세 곳이 흔들리지만 독산초 마당 양수도 아침 한 차례밖에 할 수 없다.', 0, 615743.012708557, 8265.136420490437);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1154563000', 280, 'Doksan 3-dong', '독산3동', 'Geumcheon-gu', '금천구', 'M406.9,821.77 L403.91,822.81 L394.93,821.41 L387.05,825.22 L380.06,824.69 L382.93,797.6 L384.44,792.6 L387.88,796.29 L413.87,790.61 L411.25,796.02 L411.24,798.1 L413.12,800.49 L416.46,800.88 L419.25,800.66 L420.13,805.2 L419.24,810.19 L417.25,816.16 L416.82,816.72 L406.9,821.77 Z', 'held', '["free-city"]', 'Merchants at Nammun Market trade filter cloth from Gasan for grain and kimchi jars brought from the residential areas.', '남문시장의 상인들은 가산 쪽 필터 원단과 주거지에서 가져온 곡물·김치통을 교환한다.', 'Nammun Market uses a temporary exchange sheet instead of central parts prices. Inspection is possible only in the morning, and the residents of Hanyang Suzain are discussing sealing the water tank after halving the water used for market cooking.', '남문시장은 중앙 부품 가격 대신 임시 교환표를 쓴다. 검수는 오전만 가능하고 한양수자인 주민들은 시장 취사용 물을 절반으로 줄인 뒤 저수조 봉인을 논의 중이다.', 0, 945297.0321387636, 7146.3251976108495);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1154564000', 281, 'Doksan 4-dong', '독산4동', 'Geumcheon-gu', '금천구', 'M421.21,844.43 L407.84,839.63 L405.13,839.26 L400.92,840.76 L390.65,842.59 L378.86,842.35 L380.06,824.69 L387.05,825.22 L394.93,821.41 L403.91,822.81 L409.39,820.54 L410.55,822.5 L414.75,833.37 L418.98,842.2 L421.21,844.43 Z', 'held', '["free-city"]', 'The building association and the guard unit are quarreling over the seats of the Gumin Culture and Sports Center Theater. Residents want to keep them as night evacuation seats for slope households such as Taeyeong Villa, but the guard unit wants to use them as a staging site, and in the meantime the Jeongsim Elementary School yard handles daytime water supply.', '구민문화체육센터극장의 객석을 두고 건물조합과 경비대가 다툰다. 주민들은 태영빌라 등 사면 가구의 야간 대피석으로 남기려 하지만 경비대는 편성 장소로 쓰려 하고, 정심초 운동장에서는 그 사이 낮 급수를 맡는다.', 'On opening day, the community center temporarily assigned turns for the theater evacuation.', '개막일 주민센터는 극장 대피 순번을 임시로 붙였다.', 0, 619149.1204341935, 6674.482549699792);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1154567000', 282, 'Siheung 1-dong', '시흥1동', 'Geumcheon-gu', '금천구', 'M402.3,898.69 L401.63,902.53 L400.68,904.1 L398.88,905.6 L393.62,907.22 L395.08,912.21 L395.44,914.54 L395.21,915.08 L387.03,921.73 L385.93,922.22 L383.67,922.02 L380.06,921.05 L374.05,916.72 L371.15,907.42 L370.45,898.69 L368.33,892.23 L369.45,892.6 L371.66,891.74 L370.6,888.74 L368.25,884.06 L366.88,880.19 L365.66,875.2 L376.34,869.98 L381.88,868 L383.64,873.14 L385.87,872.46 L390.69,867.9 L392.63,863.78 L392.88,859.99 L393.87,857.96 L398.08,857.66 L398.76,860.37 L402.66,885.56 L402.95,888.59 L402.3,898.69 Z', 'held', '["free-city"]', 'When Siheungcheon Stream overflows into the back alleys of Daemyeong Market, trade and passage toward Geumcheon-gu Office Station stop together. In the opening-day state, the community center sets a temporary order for streamside households after the central water supply contract ends and has set up a sandbag workshop in the Siheung Elementary School yard.', '시흥천이 대명시장 뒷골목으로 넘치면 장사와 금천구청역 방향 통행이 함께 멈춘다. 주민센터는 중앙 급수 계약이 끝난 뒤 천변 가구의 임시 순서를 정하고 시흥초 운동장에 모래주머니 작업장을 마련한 개막 상태다.', 'Geumcheon-gu Office Station keeps daytime internal passage open, but I Gangmuk''s demand for a night closure is posted only on the Samgeori bulletin board.', '금천구청역은 주간 내부 통과를 유지하지만 이강묵의 야간 차단 요구는 삼거리 게시판에만 붙어 있다.', 1, 1475868.6223250686, 6291.007112389839);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1154568000', 283, 'Siheung 2-dong', '시흥2동', 'Geumcheon-gu', '금천구', 'M466.58,903.46 L457.96,911.22 L453.29,914.34 L445.66,923.36 L421.47,907.72 L421,907.32 L420.3,903.8 L421.53,898.82 L424.73,891.56 L425.91,890.51 L427.48,891.06 L428.21,890.95 L432.56,888.3 L437.57,882.31 L438.35,877.67 L438.25,876.39 L449.9,876.15 L449.78,878.01 L450.35,882.29 L451.89,886.31 L462.98,896.24 L467.76,901.66 L466.58,903.46 Z', 'held', '["free-city"]', 'Rockfall piles up on the sidewalk climbing to Byeoksan Complex 3 and Building 508, delaying water hauling. Residents negotiate where to assign labor first: installing ropes below Kalbawi or running the evacuation floor of Geumcheon Comprehensive Welfare Town.', '벽산3단지와 508동으로 오르는 인도에 낙석이 쌓여 물 운반이 늦어진다. 주민들은 칼바위 아래에 밧줄을 설치하는 작업과 금천종합복지타운의 대피 마루 운영 중 어디에 먼저 인력을 쓸지 협의한다.', 'On opening day, central raw water does not reach the rooftops of the housing complex, so the community center sets a temporary water supply order. One lane of sidewalk below Kalbawi is blocked by stone, and the evacuation floor at the Welfare Town can be opened only until the afternoon.', '개막일 단지 옥상까지 중앙 원수가 닿지 않아 주민센터가 임시 급수 순서를 정한다. 칼바위 아래 인도 한 줄은 돌에 막혀 있고 복지타운 대피 마루는 오후까지만 열 수 있다.', 0, 1179303.9872674432, 5003.2901301994025);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1154569000', 284, 'Siheung 3-dong', '시흥3동', 'Geumcheon-gu', '금천구', 'M428.72,937.91 L426.17,937.95 L425.56,938.48 L420.47,943.13 L417.54,946.88 L416.02,950.27 L414.73,954.55 L411.06,959.63 L408.44,960.72 L405.67,961.03 L397.73,959.3 L390.47,950.93 L383.23,944.51 L381.81,942.12 L381.36,940.3 L382.45,939.25 L382.53,934.07 L382.02,929.24 L380.06,921.05 L384.47,922.18 L385.93,922.22 L387.03,921.73 L395.21,915.08 L395.44,914.54 L394.74,911.13 L405.88,916.96 L423.85,931.28 L428.72,937.91 Z', 'held', '["free-city"]', 'Residents of Siheung 3-dong are set to haul water via Bullocheon Spring and Geumcheon Waterfall Park. Bakmisarang Village Hall handles temporary distribution, but since whether the spring water is drinkable is not confirmed by the data, heating alone does not guarantee safety and separate water quality testing is required.', '시흥3동 주민들은 불로천약수터와 금천폭포공원을 거쳐 물을 운반하는 것으로 설정한다. 박미사랑마을회관이 임시 배분을 맡지만 약수의 음용 가능 여부는 자료로 확인되지 않았으므로 가열만으로 안전을 보장하지 않으며 별도 수질 확인이 필요하다.', 'On opening day, the community center issues a temporary distribution table in response to the suspension of central water supply. The safety of the spring water has not yet been confirmed, and Geumcheon Ramp accepts light handcarts only in the daytime, leaving the night post empty.', '개막일 주민센터는 중앙 급수 중단에 대응해 임시 배분표를 발급한다. 약수의 안전성은 아직 확인하지 않았으며 금천램프는 가벼운 손수레를 주간에만 받고 야간 초소는 비워 둔 상태다.', 0, 1334898.4553945572, 2217.0225668028493);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1154570000', 285, 'Siheung 4-dong', '시흥4동', 'Geumcheon-gu', '금천구', 'M425.06,847.08 L422.98,850.23 L422.48,851.77 L426.06,872.96 L423.41,873.08 L415.41,877.9 L413.74,880.01 L410.67,890.33 L402.95,888.59 L398.76,860.37 L398.08,857.66 L406.48,849.95 L413.36,845.63 L414.12,845.43 L417.07,847.11 L421.31,845.63 L425.06,847.08 Z', 'held', '["free-city"]', 'Hauling teams going back and forth between Sunheung Spring and Sangiseuk Park B handle temporary water storage for Geumgang Apartments and Siheung Samik Apartments. In the opening-day setting, residents hand over water jugs at Doksan-ro 22-gil and the Sinheung Elementary School yard, but the drinking safety of the spring water requires water quality testing.', '순흥약수터와 산기슭공원B를 오가는 운반조가 금강아파트·시흥 삼익아파트의 임시 물 저장을 맡는다. 개막 설정의 주민들은 독산로22길과 신흥초 운동장에서 물통을 인계하지만 약수의 음용 안전성은 수질 검사가 필요하다.', 'On opening day, two water tanks on the roof of Geumgang Apartments are tilted and need repair first. The park footpath has been adjusted to be used only in the morning, and whether the World Meridian complex''s own water storage will be sealed is still under negotiation.', '개막일 금강아파트 옥상 물통 두 개가 기울어 우선 보수가 필요하다. 공원 오솔길을 아침만 이용하도록 조정했으며 월드메르디앙의 자체 저수 봉인 여부는 아직 협의 중이다.', 0, 770696.111295481, 7071.269622522559);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1154571000', 286, 'Siheung 5-dong', '시흥5동', 'Geumcheon-gu', '금천구', 'M438.25,876.39 L437.57,882.31 L432.56,888.3 L428.21,890.95 L427.48,891.06 L425.91,890.51 L424.73,891.56 L421.53,898.82 L420.3,903.22 L420.35,904.37 L421,907.32 L421.47,907.72 L445.66,923.36 L445.27,925.17 L442.26,933.37 L440.81,935.39 L436.85,938.54 L428.72,937.91 L423.85,931.28 L405.88,916.96 L394.74,911.13 L393.62,907.22 L398.88,905.6 L400.68,904.1 L401.63,902.53 L402.3,898.69 L402.95,888.59 L410.67,890.33 L413.74,880.01 L415.41,877.9 L423.41,873.08 L426.06,872.96 L428,874.51 L438.25,876.39 Z', 'held', '["free-city"]', 'The tilted retaining wall of Yaksu Villa threatens water hauling on Siheung-daero 40-gil. Residents must use the same workers for rooftop pumping at Sindo Brenua Apartments and for the wall repair; the Geumcheon Elementary School yard is set as the daytime distribution site, and the Hwain Electronics Industry site as the retrieval point for circuit boards used to repair flashlights.', '약수빌라의 기운 옹벽이 시흥대로40길 물 운반을 위협한다. 주민들은 신도브래뉴아파트 옥상 양수와 옹벽 보수에 같은 작업자를 써야 하며 금천초 운동장은 낮 배급, 화인전자산업 터는 손전등 수리용 기판 회수 장소로 설정된다.', 'The community center put households with retaining wall cracks at the top of its list. One side of the piles at Yaksu Villa is lifted, Geumcheon Elementary School distribution runs only in the morning, and night access to the Hwain Electronics site has been halted.', '주민센터는 옹벽 균열이 있는 가구를 우선 명단에 올렸다. 약수빌라 말뚝 한쪽이 들떠 있으며 금천초 배급은 오전만 진행하고 화인전자 터의 야간 출입은 중단했다.', 0, 1425853.1633702496, 3595.3211254115886);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156051500', 287, 'Yeongdeungpo-bondong', '영등포본동', 'Yeongdeungpo District', '영등포구', 'M416.18,683.51 L415.93,676.92 L408.56,677.52 L403.74,681.84 L401.92,684.4 L392.13,685.88 L388.47,677.73 L381.4,680.59 L380.37,678.74 L398.23,669.24 L397.84,668.18 L403.9,665.52 L418.91,660.96 L432.48,659.99 L434.56,659.32 L434.66,660.62 L436.22,665.37 L437.49,668 L439.09,669.75 L440.76,670.99 L437.66,675.8 L435.59,678.34 L432.69,679.47 L416.18,683.51 Z', 'held', '["free-city"]', 'The handover teams around Yeongdeungpo Station do not want to receive long-distance supplies and residents'' rations in the same order. Once unloading of large freight begins, stretcher handovers toward Yosep Clinic get backed up.', '영등포역 주변 인계조는 장거리 물자와 주민 배급을 같은 순서로 받지 않으려 한다. 큰 화물의 하역이 시작되면 요셉의원 쪽 들것 인계가 밀린다.', 'Residents of Yeongdeungpo-bondong negotiate the cost of their next choice: clearing the daily-life handover section first.', '영등포본동 주민들은 다음 선택의 비용을 협의한다: 생활 인계 구간을 먼저 비운다.', 1, 807639.8017261397, 7499.258935796913);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156053500', 288, 'Yeongdeungpo-dong', '영등포동', 'Yeongdeungpo District', '영등포구', 'M424.82,634.2 L432.79,648.92 L437.01,652.16 L434.56,659.32 L432.48,659.99 L418.91,660.96 L403.9,665.52 L397.84,668.18 L396.56,667.89 L395.06,666.97 L394.13,665.94 L392.84,663.46 L390.92,657.02 L389.76,651.84 L389.76,648.42 L393.09,634.63 L395.15,627.88 L402.82,606.23 L405.51,605.53 L405.81,606.5 L405.4,621.97 L406.02,625.74 L407.11,629.58 L408.38,629.91 L412.51,627.96 L416.58,627.27 L419.68,628.83 L422.73,635.36 L424.82,634.2 Z', 'held', '["free-city"]', 'Merchants around Yeongdeungpo Market want to separate the goods they will sell today from the rations residents have already reserved.', '영등포시장 주변 상인들은 오늘 팔 물건과 이미 예약한 주민 배급분을 분리하려 한다.', 'Residents of Yeongdeungpo-dong negotiate the cost of their next choice: storing the reserved ration portions separately.', '영등포동 주민들은 다음 선택의 비용을 협의한다: 배급 예약분을 별도 보관한다.', 2, 1414765.2805348213, 6618.695078847411);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156054000', 289, 'Yeoui-dong', '여의동', 'Yeongdeungpo District', '영등포구', 'M451.68,573.28 L453.34,576.14 L466.5,581.86 L474.09,573.66 L489.95,582.12 L505.37,591.37 L515.22,601.15 L526.5,619.95 L529.35,626.42 L528.9,658.6 L499.73,664.47 L478.95,666.08 L461.35,664.37 L459.17,663.86 L443.43,656.49 L439.34,654.11 L432.79,648.92 L421.36,627.55 L420.38,623.6 L413.83,604.64 L409.77,599.08 L405.86,581.18 L401.65,573.21 L436.38,573.06 L451.68,573.28 Z', 'held', '["free-city"]', 'Residents traveling around Yeouinaru and Saetgang want to separate waterside waiting from inland handovers. A wide stretch of water does not mean free crossing, so only confirmed docking and walking routes are used.', '여의나루와 샛강 주변을 오가는 주민들은 물가 대기와 내륙 인계를 분리하려 한다. 넓은 수면이 있다고 자유롭게 도하할 수 있는 것은 아니어서 확인된 접안과 보행만 사용한다.', 'Residents of Yeoui-dong negotiate the cost of their next choice: moving the waiting zone to higher ground.', '여의동 주민들은 다음 선택의 비용을 협의한다: 대기 구획을 높은 쪽으로 옮긴다.', 5, 8202924.467414119, 1240.3137491289497);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156055000', 290, 'Dangsan 1-dong', '당산1동', 'Yeongdeungpo District', '영등포구', 'M393.37,633.71 L389.76,648.42 L390,653.35 L388.56,652.46 L385.98,651.69 L364.69,647.07 L362.21,642.75 L365.93,623.75 L370.31,616.59 L379.12,621.92 L395.15,627.88 L393.37,633.71 Z', 'held', '["free-city"]', 'The handover team at Yeongdeungpo-gu Office Station records supplies received from nearby housing complexes and labor promises separately, to clarify responsibility for parts exchange.', '영등포구청역 인계조는 주변 단지에서 받은 물자와 노동 약속을 별도 기록해 부품 교환의 책임을 분명히 한다.', 'Residents of Dangsan 1-dong negotiate the cost of their next choice: separating supply receipt from labor reservations.', '당산1동 주민들은 다음 선택의 비용을 협의한다: 물자 수령과 노동 예약을 구분한다.', 1, 742955.2693944721, 8468.746718935128);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156056000', 291, 'Dangsan 2-dong', '당산2동', 'Yeongdeungpo District', '영등포구', 'M405.86,581.18 L409.77,599.08 L413.83,604.64 L420.38,623.6 L421.36,627.55 L424.82,634.2 L422.73,635.36 L419.68,628.83 L416.58,627.27 L412.51,627.96 L408.38,629.91 L407.11,629.58 L406.02,625.74 L405.4,621.97 L405.81,606.5 L405.51,605.53 L402.82,606.23 L395.15,627.88 L379.12,621.92 L370.31,616.59 L389.47,586.44 L371.04,570.05 L374.88,571.25 L377.44,567.19 L381.12,568.7 L383.9,568.09 L387.51,571.33 L390.07,569.67 L389.39,567.57 L393.68,563.27 L401.65,573.21 L405.86,581.18 Z', 'held', '["free-city"]', 'The guide team around Dangsan Station wants to set up a rest area that waiting residents and freight porters can share. If every seat is removed to widen the passage, residents with difficulty moving will struggle to hold out.', '당산역 주변 안내조는 기다리는 주민과 화물 짐꾼이 함께 쓸 휴식 공간을 마련하려 한다. 통로를 늘리려고 모든 자리를 없애면 거동이 어려운 주민이 버티기 어렵다.', 'Residents of Dangsan 2-dong negotiate the cost of their next choice: securing care waiting seats beside the passage.', '당산2동 주민들은 다음 선택의 비용을 협의한다: 돌봄 대기석을 통로 옆에 확보한다.', 2, 1633785.755608449, 6651.178076866693);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156058500', 292, 'Dorim-dong', '도림동', 'Yeongdeungpo District', '영등포구', 'M416.18,683.51 L381.43,702.62 L372.67,692.42 L366.48,687.67 L381.4,680.59 L388.47,677.73 L392.13,685.88 L401.92,684.4 L403.74,681.84 L408.56,677.52 L415.93,676.92 L416.18,683.51 Z', 'held', '["free-city"]', 'The repair crew managing the toolbox at Dorim-dong Community Center wants to let even households with few supplies borrow tools. The management team, which demands collateral, and residents who offer to pay back with labor are negotiating.', '도림동 주민센터의 공구함을 관리하는 수리반은 물자가 적은 가구도 대여할 수 있게 하려 한다. 담보를 요구하는 관리조와 노동으로 갚겠다는 주민이 협의한다.', 'Residents of Dorim-dong negotiate the cost of their next choice: recognizing repair labor as payment for rentals.', '도림동 주민들은 다음 선택의 비용을 협의한다: 수리 노동을 대여 대가로 인정한다.', 0, 549408.5157642954, 9566.105819617065);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156060500', 293, 'Mullae-dong', '문래동', 'Yeongdeungpo District', '영등포구', 'M382.91,650.93 L388.18,652.31 L390,653.35 L392.3,661.82 L393.54,664.94 L395.06,666.97 L396.56,667.89 L397.84,668.18 L398.23,669.24 L380.37,678.74 L381.4,680.59 L366.48,687.67 L362.99,686.18 L359.95,680.89 L356.96,678.16 L334.42,664.59 L327.96,661.1 L329.02,644.52 L343.92,647.47 L344.95,643.14 L382.91,650.93 Z', 'held', '["free-city"]', 'The fabrication team around Mullae Station wants to extend metalworking hours, but nearby camping households demand time to rest at night.', '문래역 주변 제작조는 금속 작업 시간을 늘리려 하지만 가까운 숙영 가구는 밤에 쉴 시간을 요구한다.', 'Residents of Mullae-dong negotiate the cost of their next choice: grouping noisy work into the daytime.', '문래동 주민들은 다음 선택의 비용을 협의한다: 시끄러운 작업을 주간에 모은다.', 1, 1741661.1476546992, 5349.548052183572);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156061000', 294, 'Yangpyeong 1-dong', '양평1동', 'Yeongdeungpo District', '영등포구', 'M370.31,616.59 L365.93,623.75 L362.73,639.77 L362.21,642.75 L364.69,647.07 L361.26,646.68 L344.95,643.14 L343.92,647.47 L329.02,644.52 L329.09,641.59 L331.13,630.69 L334.66,626.77 L345.05,622.18 L347.84,620.61 L349.69,618.46 L354.11,611.06 L358.58,612.32 L370.31,616.59 Z', 'held', '["free-city"]', 'In the space marked as the Suhwa Industrial Complex, salvage teams pick out parts usable for daily-life facilities before dismantling equipment whose function they do not know.', '수화공단으로 표시된 공간에서 회수조는 기능을 모르는 장비를 분해하기 전에 생활 설비에 쓸 수 있는 부품을 골라낸다.', 'Residents of Yangpyeong 1-dong negotiate the cost of their next choice: running a function test before disassembly.', '양평1동 주민들은 다음 선택의 비용을 협의한다: 분해 전에 기능 검사를 한다.', 1, 864132.8560243102, 6817.007314248305);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156062000', 295, 'Yangpyeong 2-dong', '양평2동', 'Yeongdeungpo District', '영등포구', 'M392.47,559.44 L393.68,563.27 L389.39,567.57 L390.07,569.67 L387.51,571.33 L383.9,568.09 L381.12,568.7 L377.44,567.19 L374.88,571.25 L371.04,570.05 L389.47,586.44 L370.31,616.59 L358.58,612.32 L360.03,608.29 L355.07,606.26 L355.07,603.48 L358.6,601.82 L359.28,596.86 L353.79,589.19 L345.89,570.99 L344.88,564.67 L339.46,557.56 L332.25,549.18 L324.95,535.9 L324.58,529.13 L328.04,529.96 L328.41,524.09 L331.5,519.28 L360.74,537.48 L384.65,549.36 L392.47,559.44 Z', 'held', '["free-city"]', 'The fictional water technicians around the Yeongdeungpo Arisu Water Purification Center demand inspections and equipment checks before increasing the supply volume. The distribution team urges them to send residents'' same-day water first.', '영등포아리수정수센터 주변의 창작 물 기술자들은 급수량을 늘리기 전에 검사와 장비 점검을 요구한다. 배급조는 주민의 당일 물부터 보내 달라고 재촉한다.', 'Residents of Yangpyeong 2-dong negotiate the cost of their next choice: publishing test results together with water supply allocations.', '양평2동 주민들은 다음 선택의 비용을 협의한다: 검사 결과와 급수 배정을 함께 공개한다.', 1, 2891935.8102742876, 2318.9311381582656);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156063000', 296, 'Singil 1-dong', '신길1동', 'Yeongdeungpo District', '영등포구', 'M461.35,664.37 L454.14,676.26 L451.02,685.78 L449.99,690.39 L449.86,693.45 L445.51,696.4 L435.7,699.79 L432.77,701.82 L429.06,694.07 L426.06,681.13 L432.69,679.47 L435.59,678.34 L439.16,673.77 L440.76,670.99 L439.09,669.75 L437.49,668 L436.22,665.37 L434.66,660.62 L434.56,659.32 L437.01,652.16 L439.34,654.11 L443.43,656.49 L459.17,663.86 L461.35,664.37 Z', 'held', '["free-city"]', 'The fictional medical team in the Seongae Hospital building wants to fix stretcher handles and wheels first, but the hauling team is also waiting for the same parts.', '성애병원 건물의 창작 의무조는 들것 손잡이와 바퀴부터 고치려 하지만 운반조도 같은 부품을 기다린다.', 'Residents of Singil 1-dong negotiate the cost of their next choice: repairing the damaged stretchers first.', '신길1동 주민들은 다음 선택의 비용을 협의한다: 손상된 들것을 먼저 수리한다.', 1, 811209.8442015207, 6978.465609687171);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156065000', 297, 'Singil 3-dong', '신길3동', 'Yeongdeungpo District', '영등포구', 'M412.02,706.81 L410.96,705.82 L408.03,704.87 L395.25,706.77 L389.09,710.05 L387.86,710.97 L381.43,702.62 L416.18,683.51 L417.85,690.14 L418.08,701.11 L415.64,708.24 L412.02,706.81 Z', 'held', '["free-city"]', 'The fictional laundry team in the Dorim Elementary School yard wants to wash work clothes and camp bedding on the same day, but there is not enough drying space.', '도림초등학교 마당의 창작 세탁조는 작업복과 숙영 침구를 같은 날 씻으려 하지만 건조 자리는 충분하지 않다.', 'Residents of Singil 3-dong negotiate the cost of their next choice: dividing drying time for bedding and work clothes.', '신길3동 주민들은 다음 선택의 비용을 협의한다: 침구와 작업복의 건조 시간을 나눈다.', 0, 480059.52018029516, 10028.756430435675);
