INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156069000', 301, 'Singil 7-dong', '신길7동', 'Yeongdeungpo District', '영등포구', 'M444.55,716.58 L436.92,715.34 L431.03,721.03 L420.38,721.5 L420.9,720.08 L422.67,717.57 L423.47,716.75 L425.31,715.76 L427.96,711.9 L430.82,707.04 L432.77,701.82 L435.7,699.79 L445.51,696.4 L449.86,693.45 L449.99,690.39 L451.02,685.78 L454.14,676.26 L458.9,668.67 L464.31,672.2 L464.42,675.55 L462.43,676.46 L459.51,676.77 L447.11,714.73 L446.17,717.2 L444.55,716.58 Z', 'held', '["free-city"]', 'Around Daebang Station, the fictional guard team and the residents'' representatives want to separate civilian passage checks from service registration. Even if traces of a military organization remain, it is not regarded as having taken over current institutional operations.', '대방역 주변에서 창작 경비조와 주민 대표는 민간 통과 확인을 복무 등록과 분리하려 한다. 군사 조직의 흔적이 있어도 현재 기관 운영을 이어받았다고 보지 않는다.', 'Residents of Singil 7-dong negotiate the cost of their next choice: separating civilian handovers from service consultations.', '신길7동 주민들은 다음 선택의 비용을 협의한다: 민간 인계와 복무 협의를 분리한다.', 4, 547650.1970023683, 10575.181076717397);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156070000', 302, 'Daerim 1-dong', '대림1동', 'Yeongdeungpo District', '영등포구', 'M404.32,761.83 L391.76,749.25 L386.09,740.46 L397.09,731.67 L407.24,732.24 L409.78,731.19 L413.35,748.71 L404.32,761.83 Z', 'held', '["free-city"]', 'The fictional medical team in the Gangnam Seongsim Hospital building must accurately receive explanations from residents who speak different languages. If interpreters are shared with the ration counter, waiting times grow longer.', '강남성심병원 건물의 창작 의무조는 서로 다른 언어를 쓰는 주민의 설명을 정확하게 받아야 한다. 통역을 배급 창구와 나눠 쓰면 대기 시간이 길어진다.', 'Residents of Daerim 1-dong negotiate the cost of their next choice: stationing interpreter shifts for medical requests.', '대림1동 주민들은 다음 선택의 비용을 협의한다: 의무 요청용 통역 교대를 둔다.', 0, 481351.356622442, 8212.504121185424);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156071000', 303, 'Daerim 2-dong', '대림2동', 'Yeongdeungpo District', '영등포구', 'M395.33,775.96 L394,775.87 L387.38,773.46 L382.09,769.6 L379.14,766.46 L372.96,750.19 L386.09,740.46 L391.76,749.25 L404.32,761.83 L395.33,775.96 Z', 'held', '["free-city"]', 'Households along Dorimcheon Stream want to move goods out of the low warehouses, but the distribution team must also handle same-day arrivals.', '도림천을 접한 가구들은 물품을 낮은 창고에서 옮기려 하지만 배급조는 당일 반입도 처리해야 한다.', 'Residents of Daerim 2-dong negotiate the cost of their next choice: moving essential ration stock to higher storage.', '대림2동 주민들은 다음 선택의 비용을 협의한다: 필수 배급 재고를 높은 보관소로 옮긴다.', 0, 578455.9368330662, 5927.331334468561);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156072000', 304, 'Daerim 3-dong', '대림3동', 'Yeongdeungpo District', '영등포구', 'M381.43,702.62 L392.69,716.74 L391.18,719.96 L389.35,722.79 L389.76,724.1 L393.74,729.14 L395.33,730.7 L397.09,731.67 L386.09,740.46 L372.96,750.19 L370.65,742.19 L367.8,729.93 L367.6,728.02 L367.38,712.67 L368.41,705.85 L368.97,694.82 L372.67,692.42 L381.43,702.62 Z', 'held', '["free-city"]', 'The repair team around Daerim Station wants to return commuters'' equipment in a short time, but residents'' large repairs are also backed up.', '대림역 주변 수선조는 출근 통행객의 장비를 짧은 시간에 돌려주려 하지만 주민의 큰 수리도 밀려 있다.', 'Residents of Daerim 3-dong negotiate the cost of their next choice: booking separate time for urgent residential repairs.', '대림3동 주민들은 다음 선택의 비용을 협의한다: 주거지 긴급 수리 시간을 따로 예약한다.', 1, 936827.3754003235, 6593.850865385233);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159051000', 305, 'Noryangjin 1-dong', '노량진1동', 'Dongjak-gu', '동작구', 'M563.71,676.73 L550.31,687.31 L542.24,695.25 L541.35,695.12 L540.66,694.26 L530.85,694.68 L529.3,697 L522.25,698.71 L508.37,699.83 L502.94,701.06 L502.11,700.44 L503.84,698.13 L507.86,698.1 L508.91,696.96 L512.88,690.74 L512.2,688.44 L509.36,687.14 L506.23,688.8 L502.08,674.9 L498.93,671.46 L499.73,664.47 L528.9,658.6 L550.74,667.37 L563.71,676.73 Z', 'held', '["free-city"]', 'Nodeul Platform calls only the south-bank box turns, and Noryangjin Platform is the signature waiting seats. The two valves of the Noryangjin distribution reservoir split the ice-making raw water and Geonyeong Apartments'' stored water between the same morning shift.', '노들 승강장은 남안 상자 순번만 부르고, 노량진 승강장은 서명 대기석이다. 노량진 배수지 두 동 밸브가 제빙 원수와 건영아파트 저수를 같은 아침 교대에 나눈다.', 'The fictional distribution team and the water technicians of Noryangjin 1-dong negotiate priorities among reservoir, warehouse, and household water allocations.', '노량진1동의 창작 배급조와 물 기술자는 배수지·창고·가구 물 배정의 우선순위를 협의한다.', 3, 1626496.4462884932, 6162.140730691927);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159052000', 306, 'Noryangjin 2-dong', '노량진2동', 'Dongjak-gu', '동작구', 'M502.94,701.06 L499.06,703.12 L496.49,702.86 L496.14,702.68 L496.11,701.81 L495.03,700.52 L490.61,697.13 L489.51,696.85 L487.66,697.14 L486.54,690.03 L486.57,684.45 L485.27,675.37 L481.47,670.14 L481.49,665.7 L499.73,664.47 L498.93,671.46 L502.08,674.9 L506.23,688.8 L509.36,687.14 L512.2,688.44 L512.88,690.74 L508.23,697.76 L507.86,698.1 L503.84,698.13 L502.11,700.44 L502.94,701.06 Z', 'held', '["free-city"]', 'A construction fence runs between Noryangjin 2-dong Community Center and the Seoul Noryangjin Elementary School yard. The planned lot of the Noryangjin Station Youth Housing Apartments remains an empty lot where stretchers and square timber lie on the same dirt ground, and the planned sites of Rakeullache Jai Deupain and Deupain Areutia likewise read only as piles of timber. The Cheonghwa Hospital building is a fictional waiting-bed ward, and actual medical operation is not read from the tag. Jangseungbaegi-ro 27-gil backs up as far as the front of Leaders Tower when carts get blocked.', '노량진2동주민센터와 서울노량진초등학교 운동장 사이로 공사 펜스가 이어진다. 노량진역청년주택아파트 예정 필지는 빈 터로 남아 들것과 각재가 같은 흙바닥에 놓이고, 라클라체자이드파인·드파인아르티아 예정지도 각재 더미로만 읽힌다. 청화병원 건물은 창작상 대기 침상이며 실제 진료 가동을 태그로 읽지 않는다. 장승배기로27길은 수레가 막히면 리더스타워 앞까지 역류한다.', 'In response to the opening-day supply gap, Noryangjin 2-dong Community Center wants to divide the personnel to assign to vacant lot access and to the fictional waiting room in the Cheonghwa Hospital building.', '노량진2동 주민센터는 개막일 공급 공백에 대응해 공터 출입과 청화병원 건물의 창작 대기실에 배정할 인력을 나누려 한다.', 0, 648502.4106218244, 3419.108338971191);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159053000', 307, 'Sangdo 1-dong', '상도1동', 'Dongjak-gu', '동작구', 'M542.62,698.4 L540.98,708.06 L548.91,725.36 L551.41,727.27 L561.76,730.91 L566.88,742.54 L564.73,743.98 L561.85,749.7 L561.76,746.72 L558.98,744.9 L555.82,744.97 L555.31,745.23 L554.51,748.32 L550.75,752.33 L548.86,753.24 L547.12,753.13 L543.37,754.57 L541.18,755.06 L539.34,754.61 L533.2,750.07 L525.4,745.47 L523,745.23 L522.18,744.61 L523.54,736.82 L524.75,734.03 L524.83,727.37 L523.68,725.38 L523.79,721.28 L521.96,717.87 L519.66,714.53 L524,707.86 L527.8,705.1 L529.35,702.6 L530.91,699.52 L530.47,698.24 L530.85,694.68 L540.66,694.26 L541.35,695.12 L542.62,698.4 Z', 'held', '["free-city"]', 'Sangdo·Sungsil University Station platform calls only slope turns, and the North Gate of Sungsil University is the fork between water jugs and sleeping cots. The Seoul Sanghyeon Elementary School yard is a courtyard for sending empty jugs back. With such great ups and downs in the terrain, the stairs are cut off first the day after rain.', '상도·숭실대입구 승강장은 비탈 순번만 부르고, 숭실대학교 북문이 물통과 침상의 갈림이다. 서울상현초등학교 운동장은 빈 통을 돌려보내는 마당이다. 기복이 커 빗물 다음 날 계단이 먼저 끊긴다.', 'On opening day, Sangdo 1-dong residents and the fictional medical team coordinate the shifts needed for the Sungsil University North Gate handover and slope water hauling, amid the gap in the central water supply contract.', '개막일 상도1동 주민과 창작 의무조는 중앙 급수 계약 공백 속에서 숭실대 북문 인계와 사면 물 운반에 필요한 교대를 조정한다.', 2, 1430071.7985860405, 9218.977685620583);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159054000', 308, 'Sangdo 2-dong', '상도2동', 'Dongjak-gu', '동작구', 'M500.49,720.9 L490.74,710.74 L481.61,709.35 L480.17,707.72 L479.94,706.61 L480.33,702.2 L481.5,702.12 L482.5,703.6 L483.85,703.71 L485.37,702.28 L485.75,700.13 L486.1,699.81 L486.63,698.12 L487.66,697.14 L489.51,696.85 L490.61,697.13 L495.03,700.52 L496.11,701.81 L496.14,702.68 L497.36,703.07 L499.06,703.12 L502.94,701.06 L508.37,699.83 L522.25,698.71 L529.3,697 L530.85,694.68 L530.47,698.24 L530.91,699.52 L529.35,702.6 L527.8,705.1 L524,707.86 L519.66,714.53 L521.96,717.87 L523.79,721.28 L523.68,725.38 L500.49,720.9 Z', 'held', '["free-city"]', 'Jangseungbaegi Platform cuts alley ration tickets and lower-level cart turns under one roof. Sangdo 2-dong Community Center and Seoul Sinsangdo Elementary School are the ration seats, and the rooftop water tank of Sangdo Raemian Complex 1 contends with the household lines on Sangdo-ro 31-gil for the same hose. In front of the Guripsangdo Daycare Center, it backs up first when carts get blocked.', '장승배기 승강장은 골목 배급표와 하층 수레 순번을 한 지붕에서 자른다. 상도2동주민센터와 서울신상도초등학교가 배급 좌석이고, 상도 래미안 1차 옥상 물통이 상도로31길 집줄과 같은 호스를 다툰다. 구립상도어린이집 앞은 수레가 막히면 먼저 역류한다.', 'On opening day, Sangdo 2-dong Community Center negotiates shifts to keep Jangseungbaegi passage and household rations going together, and it manages vacant-lot loading and rooftop water hauling as separate jobs.', '상도2동 주민센터는 개막일에 장승배기 통행과 가구 배급을 함께 유지할 교대를 협의하며 공터 적재와 옥상 물 운반을 별도 작업으로 관리한다.', 1, 776372.5461276938, 10307.16508448489);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159055000', 309, 'Sangdo 3-dong', '상도3동', 'Dongjak-gu', '동작구', 'M478.02,720.56 L488.59,735.06 L500.16,746.45 L505.67,750.48 L499.51,755.4 L498.48,752.85 L489.83,749.84 L482.18,747.57 L475.49,746.1 L471.93,743.98 L470.57,739.13 L470.6,738.09 L471.52,733.26 L472.86,730.18 L471.62,730.28 L468.35,726.45 L469.69,726.03 L473.28,724 L473.53,723.36 L472.77,720.96 L472.07,720.25 L469.28,719.5 L467.7,711.72 L467.83,710.43 L468.7,709.92 L475.67,709.33 L478.41,708.81 L480.17,707.72 L481.61,709.35 L490.74,710.74 L478.02,720.56 Z', 'held', '["free-city"]', 'Seongdae Traditional Market is the scale of alley livelihoods, and the Guksabong slope is the road for water jugs and firewood. Sangdo 3-dong Community Center only records the market seat turns. The Ganghyeon Middle School yard is a courtyard for setting down empty baskets. The water tanks of Gabeul Myeongga Complex 1 and Daon Apartments receive water later than the market morning. The stairs of Guksabong 2ra-gil take the day''s labor first.', '성대전통시장이 골목 생업의 저울이고, 국사봉 비탈은 물통과 땔감의 길이다. 상도3동주민센터는 시장 좌석 순번만 적는다. 강현중학교 운동장은 빈 소쿠리를 내려놓는 마당이다. 갑을명가1차와 다온아파트 저수조는 시장 아침보다 늦게 물을 받는다. 국사봉2라길 계단이 하루 인력을 먼저 가져간다.', 'Seongdae Traditional Market merchants and the Sangdo 3-dong hauling team set the order between market weighing and daily-life handovers around Guksabong.', '성대전통시장 상인과 상도3동 운반조는 시장 계량과 국사봉 주변 생활 인계의 순서를 정한다.', 0, 672743.1334020165, 10392.97118447414);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159056000', 310, 'Sangdo 4-dong', '상도4동', 'Dongjak-gu', '동작구', 'M523.85,725.58 L524.83,727.37 L524.75,734.03 L523.54,736.82 L522.18,744.61 L510.66,751.12 L509.06,750.55 L505.67,750.48 L500.16,746.45 L497.8,744.28 L488.59,735.06 L478.02,720.56 L490.74,710.74 L500.49,720.9 L523.85,725.58 Z', 'held', '["free-city"]', 'The Sangdo 4-dong Community Center and the Seoul Sangdo Elementary School playground are the alley ration yards. The rooftop water tank of Yaksu Mansion Apartment shares household lines with Lotte Castle Bien and Yangnyeong-ro 26-gil. Gukbongsan Middle School and Seoul Samseong School only handle cot and empty-container storage. The terrain is rugged, so when a hose is cut, the alleys run dry first.', '상도4동주민센터와 서울상도초등학교 운동장이 골목 배급의 마당이다. 약수맨션아파트 옥상 물통이 롯데캐슬비엔과 양녕로26길 집줄을 나눈다. 국사봉중학교와 서울삼성학교는 침상과 빈 통 적재만 한다. 기복이 커 호스가 끊기면 골목이 먼저 마른다.', 'In response to the opening-day contract gap, Sangdo 4-dong residents first negotiate the shifts needed for the Yaksu Mansion storage tank and the water handover work in the school yard.', '상도4동 주민들은 개막일 계약 공백에 대응해 약수맨션 저장통과 학교 마당의 물 인계 작업에 필요한 교대를 먼저 협의한다.', 0, 967793.777056377, 8863.355193386731);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159060500', 311, 'Heukseok-dong', '흑석동', 'Dongjak-gu', '동작구', 'M592.1,707.78 L591.29,708.3 L583.7,710.4 L577.2,716.14 L564.13,732.18 L561.76,730.91 L551.41,727.27 L548.91,725.36 L540.98,708.06 L542.62,698.4 L541.35,695.12 L542.24,695.25 L550.31,687.31 L563.71,676.73 L575.44,685.15 L598.9,696.73 L592.1,707.78 Z', 'held', '["free-city"]', 'Heukseok platform calls only slope turns, and the Daemeorisan stairs are the single line for water buckets and stretchers. Chung-Ang University Seoul Campus and Surim Science Hall are fictional pumping and cot hubs; do not read actual university operations from the tag. The Chung-Ang University Hospital building serves only as a stretcher handover window, and Heukseok-ro 13-gil is the first to be cut off the day after rain.', '흑석 승강장은 비탈 순번만 부르고, 대머리산 계단이 물통과 들것의 한 줄이다. 중앙대학교 서울캠퍼스와 수림과학관은 창작상 양수·침상 거점이며 실제 대학 운영을 태그로 읽지 않는다. 중앙대학교병원 건물은 들것 인계 창구로만 쓰고, 흑석로13길은 빗물 다음 날 먼저 끊긴다.', 'On opening day, the Heukseok-dong community checks the fictional handover at the hospital building and the actual access status of the campus and slope walkways.', '개막일 흑석동 공동체는 병원 건물의 창작 인계와 캠퍼스·사면 보행의 실제 접근 상태를 확인한다.', 1, 1724000.8961817857, 5185.438139735956);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159062000', 312, 'Sadang 1-dong', '사당1동', 'Dongjak-gu', '동작구', 'M621.44,777.95 L619.97,805.49 L620.27,808.33 L613.58,807.37 L606.5,807.5 L593.43,810.16 L588.04,811.73 L587.19,807.2 L599.15,793.56 L600.24,793.63 L602.78,789.74 L603.1,783.32 L613.13,779.39 L620.64,777.77 L621.44,777.95 Z', 'held', '["free-city"]', 'Sadang platform is the southern gate where Gwanak high-density housing and Seocho traffic overlap. The area in front of the Sadang 1-dong shopping street and the convenience store is the waiting area, and on Dongjak-daero escort carts and trade carts fight over the same lane. The Seoul Namsa Elementary School playground is the yard where empty bags are set down.', '사당 승강장은 관악 고밀 주거와 서초 통행이 겹치는 남쪽 개찰이다. 사당1동상점가와 편의점 앞이 대기석이고, 동작대로는 호송 수레와 장사 수레가 같은 차로를 다툰다. 서울남사초 운동장은 빈 가방을 내려놓는 마당이다.', 'On opening day, the Sadang 1-dong Community Center and the fictional guide team check handovers toward Gwanak and Seocho, and try to separate civilian passage from claims of external protection.', '사당1동 주민센터와 창작 안내조는 개막일에 관악·서초 방향 인계를 확인하며 민간 통행과 외부 보호권 요구를 분리하려 한다.', 1, 632252.8460421563, 10491.53047158876);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159063000', 313, 'Sadang 2-dong', '사당2동', 'Dongjak-gu', '동작구', 'M616.31,699.85 L617.14,711.32 L617.88,713.36 L619.14,715 L633.56,726.78 L635.7,728.26 L638.26,728.35 L637.98,729.7 L633.69,728.44 L629.46,725.9 L625.76,732.11 L624.05,736.4 L623.67,740.4 L623.23,756.05 L621.44,777.95 L620.64,777.77 L613.13,779.39 L611.46,770.85 L609.85,770.82 L606.12,769.64 L603.29,766.2 L597.32,757.85 L594.71,753.1 L594.52,749.16 L593.89,747.35 L581.44,744.77 L575.58,746.27 L572.76,747.44 L566.88,742.54 L561.76,730.91 L564.13,732.18 L577.2,716.14 L583.7,710.4 L591.29,708.3 L592.1,707.78 L598.9,696.73 L616.31,699.85 Z', 'held', '["free-city"]', 'Two Dongjak platform points cut the escort order between the south bank of the Han River and Sadang Pass. The road in front of the Hyeonchungwon National Cemetery sign is a fictional quiet detour and does not claim actual cemetery operations. The foot of Gaetmalsan and the Seoul Dongjak Elementary School playground are the waiting yards.', '동작 승강장 두 점이 한강 남안과 사당 고개 사이 호송 순번을 자른다. 국립현충원 표지 앞 도로는 창작상 조용한 우회로이며 실제 묘역 운영을 주장하지 않는다. 갯말산 기슭과 서울동작초 운동장이 대기 마당이다.', 'On opening day, the Dongjak Station handover team and the Sadang 2-dong guides set zones for actually confirmed foot and supply movement, and do not create a river crossing from the shared Han River boundary alone.', '개막일 동작역 인계조와 사당2동 안내자는 실제 확인된 보행·물자 이동 구획을 정하고 공유 한강 경계만으로 도하를 만들지 않는다.', 2, 2743962.1099059954, 3014.691773671537);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159064000', 314, 'Sadang 3-dong', '사당3동', 'Dongjak-gu', '동작구', 'M603.1,783.32 L599.87,783.28 L586.93,776.77 L578.67,768.49 L576.47,766.18 L567.95,750.76 L564.73,743.98 L566.88,742.54 L572.76,747.44 L575.58,746.27 L581.44,744.77 L593.89,747.35 L594.52,749.16 L594.71,753.1 L597.32,757.85 L603.29,766.2 L606.12,769.64 L609.85,770.82 L611.46,770.85 L613.13,779.39 L603.1,783.32 Z', 'held', '["free-city"]', 'The Chongshin University hill and Dongjak Chunghyo-gil converge at the Sadang gate. The Sadang 3-dong Community Center writes gate keys and water-bucket turns in the same ledger. The Seoul Namseong and Seoul Samil Elementary School playgrounds are empty-container yards. The water tanks of Sadang Lotte Castle and Gyeongnam Honorsville compete with hilltop pumping. The planned Hillstate Isu Station Central lot is used only for lumber storage.', '총신대학교 언덕과 동작충효길이 사당 통문으로 모인다. 사당3동주민센터는 통문 열쇠와 물통 순번을 같은 장부에 적는다. 서울남성초·서울삼일초 운동장은 빈 통 마당이다. 사당롯데캐슬과 경남아너스빌 저수조는 언덕 양수와 다툰다. 힐스테이트이수역센트럴 예정 필지는 각재 적재만 한다.', 'The Sadang 3-dong residents'' meeting tries to assign work shifts to maintain household water around Chongshin University and slope passage.', '사당3동 주민 회의는 총신대 주변 생활 물과 사면 통행을 유지할 작업 교대를 배정하려 한다.', 0, 893687.957825955, 7762.44094960829);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159065000', 315, 'Sadang 4-dong', '사당4동', 'Dongjak-gu', '동작구', 'M603.1,783.32 L602.78,789.74 L600.24,793.63 L599.15,793.56 L587.19,807.2 L583.22,807.08 L580.42,802.96 L577.58,800.11 L573.3,796.55 L578.28,790.08 L582.26,787.79 L585.79,787.4 L589.9,778.96 L589.24,777.85 L599.87,783.28 L603.1,783.32 Z', 'held', '["free-city"]', 'Namseong platform calls only Sadang Market crate turns, and the Sadang 4-dong Community Center records scale seats. The water tanks of Samik Greenview, Sadang Humansia, and KCC apartments compete with the market''s ice for the same morning power. The tomb of Hyogan-gong Yi Jeong-yeong is a fictional quiet detour at a field edge and does not claim tomb operations. The foot of Kkachisan Park is a water-bucket rest area rather than a firewood spot.', '남성 승강장은 사당시장 상자 순번만 부르고, 사당4동주민센터는 저울 좌석을 적는다. 삼익그린뷰·사당휴먼시아·KCC 아파트 저수조가 시장 얼음과 같은 아침 전력을 다툰다. 효간공 이정영 묘역은 창작상 조용한 우회 밭머리이며 묘역 운영을 주장하지 않는다. 까치산공원 기슭은 땔감 대신 물통 쉼터다.', 'On opening day, as central supply talks waver, Sadang Market merchants and the community center try to divide the supplies and power to be used for weighing, refrigeration, and household pumping.', '개막일 사당시장 상인과 주민센터는 중앙 공급 협의가 흔들리자 계량·냉장·가구 양수에 사용할 물자와 전력을 나누려 한다.', 1, 426936.6744105522, 9477.752187924918);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159065100', 316, 'Sadang 5-dong', '사당5동', 'Dongjak-gu', '동작구', 'M589.9,778.96 L585.79,787.4 L582.26,787.79 L578.28,790.08 L573.3,796.55 L570.79,794.19 L561.97,782.37 L562.15,781.16 L564.31,776.07 L564.31,771.63 L564.12,768.68 L561.33,754.85 L561.85,749.7 L564.73,743.98 L567.95,750.76 L576.47,766.18 L585.23,775.2 L586.93,776.77 L589.24,777.85 L589.9,778.96 Z', 'held', '["free-city"]', 'The Sadang Cultural Welfare Center is the alley cauldron, and Kkachisan Park is the dry-branch and rainwater rest area. The Sadang 5-dong Community Center records only cauldron turns. The Seoul Sinnamseong Elementary, Sangdo Middle, Dongjak High, and Seoul Haengnim Elementary School playgrounds are empty-bowl yards. The water tanks of Sadang Xi and Samho Green Apartments compete with the cauldron fire for the same wood. Dongjak Chunghyo-gil carries bowls to the welfare center.', '사당문화복지관이 골목 솥이고, 까치산공원이 마른 가지와 빗물 쉼터다. 사당5동주민센터는 솥 순번만 적는다. 서울신남성초·상도중·동작고·서울행림초 운동장은 빈 그릇 마당이다. 사당자이와 삼호그린아파트 저수조는 솥 불과 같은 나무를 다툰다. 동작충효길은 복지관으로 그릇을 나른다.', 'Sadang 5-dong residents, responding to the opening-day food supply gap, discuss the shifts needed for fictional cooking at the cultural welfare center and for checking everyday walking routes around Kkachisan.', '사당5동 주민들은 개막일 식량 조달 공백에 대응해 문화복지관의 창작 취사와 까치산 주변 생활 보행 점검에 필요한 교대를 협의한다.', 0, 661243.9818251227, 6203.307875374838);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159066000', 317, 'Daebang-dong', '대방동', 'Dongjak-gu', '동작구', 'M481.49,665.7 L481.47,670.14 L485.27,675.37 L486.57,684.45 L486.54,690.03 L487.66,697.14 L486.63,698.12 L486.1,699.81 L485.75,700.13 L485.37,702.28 L484.05,703.59 L482.5,703.6 L481.5,702.12 L480.33,702.2 L479.89,705.91 L480.17,707.72 L478.41,708.81 L475.67,709.33 L468.7,709.92 L467.83,710.43 L467.7,711.72 L469.28,719.5 L472.07,720.25 L472.77,720.96 L473.53,723.36 L473.28,724 L469.69,726.03 L468.35,726.45 L464.2,725.1 L462.56,725.1 L450.03,729.93 L447.01,728.97 L444.39,727.58 L446.17,717.2 L459.51,676.77 L462.43,676.46 L464.42,675.55 L464.31,672.2 L458.9,668.67 L461.35,664.37 L478.95,666.08 L481.49,665.7 Z', 'held', '["free-city"]', 'Sindaebang Samgeori platform calls only intersection turns, and the intersection in front of the Naval Club is the signal point for Yeongdeungpo and Daebang carts. The building name is only a survey label and does not claim naval operations. Water buckets at the foot of Yongmasan and storage at the Seongnam High School and Yeongdeungpo High School playgrounds compete for the same shift. The Dongjak Comprehensive Social Welfare Center is the alley cauldron.', '신대방삼거리 승강장은 교차로 순번만 부르고, 해군회관앞 교차로가 영등포·대방 수레의 신호다. 건물 이름은 실측일 뿐 해군 운영을 주장하지 않는다. 용마산 기슭 물통과 성남고·영등포고 운동장 적재가 같은 교대를 다툰다. 동작종합사회복지관은 골목 솥이다.', 'On opening day, the Daebang-dong guide team, amid the central parts-contract gap, tries to coordinate intersection handovers and schoolyard storage and alley rations as separate zones.', '개막일 대방동 안내조는 중앙 부품 계약 공백 속에서 교차로 인계와 학교 마당 적재·골목 배급을 다른 구획으로 조정하려 한다.', 1, 1586539.2536450075, 6316.578664521551);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159067000', 318, 'Sindaebang 1-dong', '신대방1동', 'Dongjak-gu', '동작구', 'M431.95,762.6 L424.09,768.15 L418.1,770.76 L407.48,774.74 L403.18,776 L395.33,775.96 L404.32,761.83 L415.77,745.26 L420.21,736.82 L422.25,735.09 L427.17,734.41 L428.12,747.13 L430.79,756.31 L431.95,762.6 Z', 'held', '["free-city"]', 'Sindaebang platform calls only Dorimcheon embankment turns, and the foot of Waosan is the hill for alley water supply. Dorimcheon water is treated as turbid water in the fiction, and drinking is not to be read from the tag. The Seoul Munchang Elementary School and Daebang Middle School playgrounds are compost yards. The water tank of Boramae Lotte Nakcheondae and Daerim Samgeori compete for the same hose.', '신대방 승강장은 도림천 둑 순번만 부르고, 와우산 기슭이 골목 급수의 언덕이다. 도림천 물은 창작상 탁수로 취급하며 음용을 태그로 읽지 않는다. 서울문창초·대방중 운동장은 거름 마당이다. 보라매롯데낙천대 저수조와 대림삼거리가 같은 호스를 다툰다.', 'The Sindaebang 1-dong Community Center, responding to the opening-day supply gap, manages drainage checks around Dorimcheon and household water handover separately, and does not allocate stream water for drinking without water-quality confirmation.', '신대방1동 주민센터는 개막일 공급 공백에 대응해 도림천 주변 배수 점검과 가구 물 인계를 분리 관리하며 수질 확인이 없는 하천 물을 음용으로 배정하지 않는다.', 1, 683545.1476920438, 9977.687681681402);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159068000', 319, 'Sindaebang 2-dong', '신대방2동', 'Dongjak-gu', '동작구', 'M468.35,726.45 L471.62,730.28 L472.86,730.18 L471.52,733.26 L470.6,738.09 L470.57,739.13 L471.93,743.98 L466.88,740.59 L465.8,740.39 L464.77,740.59 L462.56,743.48 L455.88,758.41 L440.35,759.77 L431.95,762.6 L430.79,756.31 L428.12,747.13 L427.17,734.41 L432.31,733.46 L442.81,730.51 L444.26,728.69 L444.39,727.58 L447.01,728.97 L450.03,729.93 L462.56,725.1 L464.2,725.1 L468.35,726.45 Z', 'held', '["free-city"]', 'The Boramae Hospital·Boramae Park stop name is a survey name, and the Seoul Metropolitan Boramae Hospital building is a fictional stretcher handover window. Do not read actual hospital operation from the tag. The Sindaebang 2-dong Community Center records only escort turns. Boramae-ro and the Dorimcheon side are the ice-crate route. The UH-1B marker is merely park debris and does not imply an aircraft formation.', '보라매병원·보라매공원 정거장 이름은 실측이고, 서울특별시 보라매병원 건물은 창작상 들것 인계 창구다. 실제 병원 가동을 태그로 읽지 않는다. 신대방2동주민센터는 호송 순번만 적는다. 보라매로와 도림천 쪽이 얼음 상자 경로다. UH-1B 표지는 공원 잔해일 뿐 항공 편성을 뜻하지 않는다.', 'On opening day, the fictional medical team at the Boramae Hospital building and the community center discuss, amid the contract gap, the shifts needed for stretcher handovers and general household supply transport.', '개막일 보라매병원 건물의 창작 의무조와 주민센터는 계약 공백 속에서 들것 인계와 일반 생활 물자 운반에 필요한 교대를 협의한다.', 2, 1032431.6430072084, 6420.860930502994);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1162052500', 320, 'Boramae-dong', '보라매동', 'Gwanak-gu', '관악구', 'M475.49,746.1 L482.18,747.57 L489.83,749.84 L498.48,752.85 L499.51,755.4 L497.99,760.51 L497.07,764.95 L497.74,766.36 L498.27,766.23 L499.07,765.43 L499.82,765.63 L501.25,766.81 L498.89,772.2 L486.22,771.44 L464.57,760.01 L455.88,758.41 L462.56,743.48 L464.77,740.59 L466.03,740.42 L467.95,741.12 L475.49,746.1 Z', 'held', '["free-city"]', 'The fictional guide team around Danggok Station handles commuter luggage and care-household handovers through the same passage. Work crews demanding fast freight handover and slowly moving residents must divide the time.', '당곡역 주변의 창작 안내조는 출근 짐과 돌봄 가구의 인계를 같은 통로에서 처리한다. 빠른 화물 인계를 요구하는 작업반과 천천히 이동하는 주민이 시간을 나눠야 한다.', 'Boramae-dong residents negotiate the cost of the next choice: separating the care handover time slots.', '보라매동 주민들은 다음 선택의 비용을 협의한다: 돌봄 인계 시간대를 분리한다.', 1, 761601.1937153084, 9014.560450605555);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1162054500', 321, 'Cheongnim-dong', '청림동', 'Gwanak-gu', '관악구', 'M561.87,750.17 L561.33,754.85 L564.12,768.68 L564.31,776.07 L562.36,775.85 L549.27,771.88 L552.37,767.19 L552.64,764.61 L552.39,763.55 L550.05,759.61 L547.12,753.13 L548.86,753.24 L550.75,752.33 L554.51,748.32 L555.31,745.23 L555.82,744.97 L558.98,744.9 L561.76,746.72 L561.87,750.17 Z', 'held', '["free-city"]', 'Residents crossing Bongcheon Pass split and carry the weight of supplies, but when an urgent order comes in, they are tempted to skip safety checks.', '봉천고개를 지나는 주민들은 물자 무게를 나눠 운반하지만 급한 주문이 들어오면 안전 확인을 생략하려 한다.', 'Cheongnim-dong residents negotiate the cost of the next choice: spreading loads before crossing the pass.', '청림동 주민들은 다음 선택의 비용을 협의한다: 고개 통과 전에 짐을 분산한다.', 0, 316304.633720227, 13372.235336081703);
