INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165056000', 347, 'Banpo 1-dong', '반포1동', 'Seocho-gu', '서초구', 'M743.47,707.63 L733.64,711.42 L726.73,713.61 L724.34,721 L712.17,725.08 L708.64,725.98 L706.34,714.5 L699.4,697.54 L701.26,695.66 L731.7,684.94 L734.64,684.15 L743.47,707.63 Z', 'held', '["arc"]', 'The Original Cooking and Exchange Team spanning the Express Bus Terminal underground mall tries to reduce indoor open flames, but the merchants want to keep their operating hours.', '고속터미널 지하상가에 걸친 창작 취사·교환조는 실내 화기를 줄이려 하지만 상인들은 운영 시간을 유지하려 한다.', 'Banpo 1-dong residents negotiate the cost of the next choice: gathering open-flame work into a separate time slot.', '반포1동 주민들은 다음 선택의 비용을 협의한다: 화기 작업을 분리한 시간대에 모은다.', 3, 1009020.4071944489, 9832.011254940036);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165057000', 348, 'Banpo 2-dong', '반포2동', 'Seocho-gu', '서초구', 'M675.91,704.57 L681.98,714.62 L682.11,715.94 L681.65,716.58 L655.93,729.21 L652.67,729.96 L650.68,730.02 L637.98,729.7 L638.26,728.35 L644.64,726.38 L647.63,725.15 L657.47,718.1 L656.5,714.56 L655.78,713.14 L652.86,712.99 L650.04,705.17 L649.9,703.08 L650.93,700.27 L649.96,694.63 L651.84,688.46 L646.5,676.5 L661.82,666.8 L675.91,704.57 Z', 'held', '["arc"]', 'The Original Inspection Team at the Sewage Facility Management Center separates its records so that the condition of drainage equipment is not confused with household water use.', '하수시설물관리센터의 창작 점검조는 배수 장비 상태와 생활 물 사용을 혼동하지 않도록 기록을 분리한다.', 'Banpo 2-dong residents negotiate the cost of the next choice: separating inflow and discharge records by facility.', '반포2동 주민들은 다음 선택의 비용을 협의한다: 시설별 유입·배출 기록을 나눈다.', 1, 1187495.630485557, 6677.329833001385);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165058000', 349, 'Banpo 3-dong', '반포3동', 'Seocho-gu', '서초구', 'M706.63,693.8 L675.91,704.57 L661.82,666.8 L674.6,658.93 L686.23,650.67 L694.92,663.25 L696.75,665.42 L698.95,667.35 L692.78,674.93 L694.39,678.37 L698.09,675.88 L700.23,678.65 L706.76,690.74 L706.63,693.8 Z', 'held', '["arc"]', 'The Original Storage Team of the underground mall spanning several dongs cannot confirm which zone it received items from and suffers return disputes.', '여러 동에 걸친 지하상가의 창작 보관조는 짐을 어느 구획에서 받았는지 확인하지 못해 반환 분쟁을 겪는다.', 'Banpo 3-dong residents negotiate the cost of the next choice: recording the recipient for each zone as well.', '반포3동 주민들은 다음 선택의 비용을 협의한다: 구획별 수령자를 함께 기록한다.', 0, 1308172.5707446507, 5386.674631152684);
