INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165060000', 352, 'Bangbae 1-dong', '방배1동', 'Seocho-gu', '서초구', 'M678.98,787.29 L662.09,791.77 L654.52,794.78 L643.15,772.18 L670.29,761.96 L675.24,759.82 L676.29,770.5 L673.67,775.2 L674.54,776.96 L675.23,779.48 L675.21,782.38 L678.23,785.49 L678.98,787.29 Z', 'held', '["arc"]', 'The Original Guidance Team in front of the Bangbae Jeil Hospital building tries to take treatment requests and simple item pickups at different times.', '방배제일병원 건물 앞의 창작 안내조는 처치 요청과 단순 물품 수령을 다른 시간에 받으려 한다.', 'Bangbae 1-dong residents negotiate the cost of the next choice: separating item pickup times.', '방배1동 주민들은 다음 선택의 비용을 협의한다: 물품 수령 시간을 분리한다.', 2, 697545.2251914879, 7046.8549170422775);
