INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165062100', 355, 'Bangbae 4-dong', '방배4동', 'Seocho-gu', '서초구', 'M675.24,759.82 L670.29,761.96 L643.15,772.18 L621.49,775.86 L623.23,756.05 L631.4,756.13 L650.91,746.61 L660.02,744.99 L665.13,746.24 L673.76,752.53 L675.24,759.82 Z', 'held', '["arc"]', 'The Original Guidance Team separates transit records in which the labels Isu and Chongsindaeipgu get mixed. They do not automatically merge item pickup counters just because the names are identical or similar.', '이수와 총신대입구 표기가 섞이는 통행 기록을 창작 안내조가 구분한다. 이름만 같거나 비슷하다고 물품 수령 창구를 자동으로 합치지 않는다.', 'Bangbae 4-dong residents negotiate the cost of the next choice: checking the handover place and the recipient together.', '방배4동 주민들은 다음 선택의 비용을 협의한다: 인계 장소와 수령자를 함께 확인한다.', 2, 940830.5046003473, 8189.785473923457);
