INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1168052100', 360, 'Nonhyeon 1-dong', '논현1동', 'Gangnam-gu', '강남구', 'M743.39,707.44 L734.64,684.15 L731.7,684.94 L734.45,683.65 L729.19,666.27 L734.15,663.31 L745.92,657.11 L754.01,653.45 L754.57,653.89 L761.63,673.25 L760.74,673.94 L761.86,673.89 L770.45,697.42 L743.39,707.44 Z', 'held', '["arc"]', 'The Original Maintenance Team around Nonil Substation checks equipment condition before changing the power allocation between homes and workshops.', '논일변전소 주변의 창작 정비조는 민가와 작업장 전력 배정을 바꾸기 전에 장비 상태를 확인한다.', 'Nonhyeon 1-dong residents negotiate the cost of the next choice: inspecting essential circuits first.', '논현1동 주민들은 다음 선택의 비용을 협의한다: 필수 회로부터 점검한다.', 0, 1245220.7424348576, 4961.770864753501);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1168053100', 361, 'Nonhyeon 2-dong', '논현2동', 'Gangnam-gu', '강남구', 'M791.7,661.85 L788.91,663.18 L791.91,662.57 L798.82,687.23 L770.45,697.42 L761.86,673.89 L760.74,673.94 L761.63,673.25 L754.57,653.89 L754.01,653.45 L784.91,641.37 L785.89,641.65 L791.7,661.85 Z', 'held', '["arc"]', 'The Original Liaison Duty Officer at Hakdong Station collects and posts handover times from different workshops, but unconfirmed messages get mixed in as well. Nonhyeon 2-dong gives priority to recording which workshop confirmed something and when, rather than sending out messages quickly.', '학동역의 창작 연락 당번은 서로 다른 작업장의 인계 시간을 모아 게시하지만 확인되지 않은 전갈도 섞인다. 논현2동은 연락을 빨리 내보내는 것보다 어느 작업장이 언제 확인했는지를 남기는 데 우선순위를 둔다.', 'Nonhyeon 2-dong residents negotiate the cost of the next choice: publicly posting only confirmed schedules.', '논현2동 주민들은 다음 선택의 비용을 협의한다: 확인된 일정만 공개 게시한다.', 1, 1439521.3705173996, 4183.473843000657);
