INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1168059000', 365, 'Samseong 2-dong', '삼성2동', 'Gangnam-gu', '강남구', 'M813.84,708.41 L808.49,709.91 L813.52,707.57 L811.29,701.89 L810.23,700.5 L801.95,693.68 L799.97,691.05 L791.91,662.57 L788.91,663.18 L791.7,661.85 L817.62,656.4 L823.67,671.5 L835.82,699.67 L813.84,708.41 Z', 'held', '["arc"]', 'The Original Handover Team of Samseong 2-dong, to which several station entities are assigned, also records the pickup location so that items are not looked up by name and exit alone.', '여러 역 객체가 배정된 삼성2동의 창작 인계조는 이름과 출입구만으로 짐을 찾지 않도록 수령 장소를 함께 기록한다.', 'Samseong 2-dong residents negotiate the cost of the next choice: writing the pickup location on the handover slip as well.', '삼성2동 주민들은 다음 선택의 비용을 협의한다: 수령 장소를 인계표에 함께 적는다.', 6, 1257570.903438381, 7189.336183972072);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1168060000', 366, 'Daechi 1-dong', '대치1동', 'Gangnam-gu', '강남구', 'M860.88,760.21 L841.55,764.89 L838.98,766.18 L835.11,768.69 L831.84,756.6 L826.17,741.37 L825.13,739.89 L824.27,737.71 L823.66,734.9 L832.74,734.34 L847.63,728.46 L860.88,760.21 Z', 'held', '["arc"]', 'The Original Education Team at the community center tries to run a study space together with care, but the guardians'' shifts do not line up.', '주민센터의 창작 교육조는 학습 공간을 돌봄과 함께 운영하려 하지만 보호자 교대가 서로 맞지 않는다.', 'Daechi 1-dong residents negotiate the cost of the next choice: dividing care time according to the guardians'' work schedules.', '대치1동 주민들은 다음 선택의 비용을 협의한다: 보호자 작업표에 맞춰 돌봄 시간을 나눈다.', 3, 807220.8658139863, 8747.791712345563);
