INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1168063000', 368, 'Daechi 4-dong', '대치4동', 'Gangnam-gu', '강남구', 'M832.74,734.34 L823.66,734.9 L813.84,708.41 L835.82,699.67 L847.63,728.46 L832.74,734.34 Z', 'held', '["arc"]', 'The Original Records Team in the Hanlim International Graduate University space tries to lend the remaining design materials to outside repair teams while preserving the originals.', '한림국제대학원대학교 공간의 창작 기록조는 남은 설계 자료를 외부 수리조에게 빌려주되 원본을 보존하려 한다.', 'Daechi 4-dong residents negotiate the cost of the next choice: separating original storage from copy lending.', '대치4동 주민들은 다음 선택의 비용을 협의한다: 원본 보관과 사본 대여를 분리한다.', 0, 702644.2622151361, 7770.646248198143);
