INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171054000', 385, 'Macheon 1-dong', '마천1동', 'Songpa-gu', '송파구', 'M1132,745.03 L1131.1,748.6 L1127.26,759.06 L1126.63,759.91 L1125.13,760.95 L1121.43,758.17 L1110.31,750.82 L1105.82,744.09 L1104.1,742.18 L1100.24,738.84 L1122.88,731.35 L1132.15,735.8 L1132,745.03 Z', 'held', '["government"]', 'The creative porters around Macheon Station want to fix the broken wheels of the handcarts together, but they are also short of replacement parts.', '마천역 주변 창작 짐꾼들은 손수레의 고장 난 바퀴를 함께 고치려 하지만 교환할 부품도 부족하다.', 'Macheon 1-dong residents negotiate the cost of the next choice: repairing the shared ration carts first.', '마천1동 주민들은 다음 선택의 비용을 협의한다: 공용 배급 수레부터 수리한다.', 1, 519155.1653365039, 8677.752434727106);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171055000', 386, 'Macheon 2-dong', '마천2동', 'Songpa-gu', '송파구', 'M1122.88,731.35 L1100.24,738.84 L1093.41,732.71 L1080.22,727.44 L1087.17,709.62 L1089.63,712.82 L1091.97,713.3 L1096.65,713.68 L1103.65,709.24 L1105.71,710.71 L1108.74,714.16 L1110.83,714.27 L1112.49,715.6 L1114.64,715.6 L1121.82,718.7 L1125.12,714.44 L1125.84,714.72 L1133.51,721.46 L1135.87,724.69 L1135.86,726.99 L1133.5,733.88 L1132.15,735.8 L1122.88,731.35 Z', 'held', '["government"]', 'The merchants of Macheon Market want to collect empty boxes jointly and use them for ration transport, but there is no one in charge of returns.', '마천시장 상인들은 빈 상자를 공동 회수해 배급 운반에 쓰려 하지만 반환 담당자가 없다.', 'Macheon 2-dong residents negotiate the cost of the next choice: opening a shared box return desk.', '마천2동 주민들은 다음 선택의 비용을 협의한다: 공동 상자 반환대를 연다.', 0, 957322.446550262, 5264.997199389674);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171056100', 387, 'Bangi 1-dong', '방이1동', 'Songpa-gu', '송파구', 'M1028.5,705.85 L1024.28,705.82 L1007.76,697.17 L1020.38,672.64 L1040.3,682.99 L1028.5,705.85 Z', 'held', '["government"]', 'The creative practice team at Bangsan High School wants to continue everyday repair training, but classes are often interrupted by emergency site assignments.', '방산고등학교의 창작 실습조는 생활 수리 교육을 이어가려 하지만 긴급 현장 차출로 수업이 자주 끊긴다.', 'Bangi 1-dong residents negotiate the cost of the next choice: recording apprenticeship practice hours on the work chart.', '방이1동 주민들은 다음 선택의 비용을 협의한다: 도제 실습 시간을 작업표에 남긴다.', 0, 585039.3102617103, 7540.518940559);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171056200', 388, 'Bangi 2-dong', '방이2동', 'Songpa-gu', '송파구', 'M1020.38,672.64 L1007.76,697.17 L995.14,687.75 L983.26,681.9 L979.18,669.14 L996.72,661.27 L996.13,662.01 L1014.66,670.68 L1020.38,672.64 Z', 'held', '["government"]', 'The creative liaison team at Songpa Naru Station wants to relay ration schedule changes to households, but conflicting notices are still posted.', '송파나루역 창작 연락조는 배급 일정 변경을 가구에게 전달하려 하지만 서로 다른 게시가 남아 있다.', 'Bangi 2-dong residents negotiate the cost of the next choice: updating the ration timetable within the same shift.', '방이2동 주민들은 다음 선택의 비용을 협의한다: 배급 시간표를 같은 교대에 갱신한다.', 1, 766981.2011249955, 10318.766598700768);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171056600', 389, 'Olyun-dong', '오륜동', 'Songpa-gu', '송파구', 'M1015.23,624.11 L1084,662.61 L1088.03,664.37 L1090.3,666.08 L1090.27,667.49 L1088.15,669.45 L1078.03,669.06 L1084.19,675.08 L1084.85,679.73 L1080.66,679.35 L1077.97,681.02 L1075.41,689.98 L1074.61,694.43 L1075.34,695.15 L1064.26,695.2 L1020.38,672.64 L1014.66,670.68 L996.13,662.01 L996.72,661.27 L1007.27,638.84 L1015.23,624.11 Z', 'held', '["government"]', 'The creative assembly team around Olympic Park Station operates a wide waiting space while sharing meals and washing water.', '올림픽공원역 주변 창작 집결조는 넓은 대기 공간을 운영하면서 식사와 세척용 물을 나눠 쓴다.', 'Oryun-dong residents negotiate the cost of the next choice: dividing assembly times according to the quantity secured.', '오륜동 주민들은 다음 선택의 비용을 협의한다: 확보한 물량에 맞춰 집결 시간을 나눈다.', 3, 3135742.6528728935, 1660.2765521048743);
