INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171058000', 391, 'Songpa 1-dong', '송파1동', 'Songpa-gu', '송파구', 'M1003.33,705.94 L1000.45,710.37 L997.73,713.17 L994.28,715.56 L989,717.86 L976.32,701.56 L971.56,693.46 L983.26,681.9 L995.14,687.75 L1007.76,697.17 L1003.33,705.94 Z', 'held', '["government"]', 'The creative care team in the Songpa Women''s Cultural Center space runs a place where children and frail elders can stay while guardians go out on transport work. The care choice for Songpa 1-dong is not adding more shift staff but coordinating guardian handover times with ration waiting times.', '송파여성문화회관 공간의 창작 돌봄조는 보호자가 운반 일을 나가는 동안 아이와 노약자의 머무를 자리를 운영한다. 송파1동의 돌봄 선택은 교대 인력을 더 넣는 것보다 보호자 인계 시각을 배급 대기와 조정하는 일이다.', 'Songpa 1-dong residents negotiate the cost of the next choice: organizing rotating guardian care.', '송파1동 주민들은 다음 선택의 비용을 협의한다: 보호자 순환 돌봄을 편성한다.', 1, 696204.2449233566, 9831.597623702406);
