INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171060000', 393, 'Seokchon-dong', '석촌동', 'Songpa-gu', '송파구', 'M993.21,723.62 L990.25,724.78 L987.52,721.43 L953.01,734.14 L952.22,735.88 L949.98,734.89 L952.28,701.33 L955.57,701.64 L959.63,700.79 L967.59,696.58 L971.56,693.46 L976.32,701.56 L993.21,723.62 Z', 'held', '["government"]', 'The creative repairers at the place marked as the Hyundai Repair Center want to adapt the remaining equipment to everyday carts.', 'Hyundai Repair Center로 표시된 장소의 창작 수리공들은 남은 장비를 생활 수레에 맞춰 사용하려 한다.', 'Seokchon-dong residents negotiate the cost of the next choice: checking the specifications of shared cart parts.', '석촌동 주민들은 다음 선택의 비용을 협의한다: 공용 수레 부품의 규격을 확인한다.', 0, 931733.1521578409, 9624.644115358082);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171061000', 394, 'Samjeon-dong', '삼전동', 'Songpa-gu', '송파구', 'M952.28,701.33 L949.98,734.89 L952.22,735.88 L950.47,739.87 L912.93,727.35 L933.39,697.68 L952.28,701.33 Z', 'held', '["government"]', 'The creative medical team in the Gangnamsu Hospital building assigns visits to nearby households together with support for treatment at the hub.', '강남수병원 건물의 창작 의무조는 주변 가구 방문과 거점 처치 지원을 함께 배정한다.', 'Samjeon-dong residents negotiate the cost of the next choice: accepting visit requests together with the ration handover.', '삼전동 주민들은 다음 선택의 비용을 협의한다: 방문 요청을 배급 인계 때 함께 받는다.', 1, 989760.1748264461, 8517.820997877896);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171062000', 395, 'Garak-bondong', '가락본동', 'Songpa-gu', '송파구', 'M1040.58,718.04 L1036.28,724.12 L1026.75,743.27 L1035.04,755.77 L1020.17,764.76 L1007.6,743.74 L1001.78,735.03 L1002.27,731.54 L1012.84,724.86 L1016.77,721.87 L1022.02,716.97 L1024.28,705.82 L1028.5,705.85 L1040.58,718.04 Z', 'held', '["government"]', 'The creative medical team in the building marked as the National Police Hospital wants to distribute treatment-preparation supplies regardless of affiliation.', '국립 경찰병원으로 표시된 건물의 창작 의무조는 소속을 따지지 않고 처치 준비 물자를 배분하려 한다.', 'Garakbon-dong residents negotiate the cost of the next choice: allocating supplies according to urgency.', '가락본동 주민들은 다음 선택의 비용을 협의한다: 긴급도 기준으로 물자를 배정한다.', 1, 1048942.26537004, 7021.644797010549);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171063100', 396, 'Garak 1-dong', '가락1동', 'Songpa-gu', '송파구', 'M1002.27,731.54 L1001.78,735.03 L1007.6,743.74 L1012.63,752.06 L983.06,763.48 L976.04,755.88 L970.23,751.11 L966.15,748.21 L950.47,739.87 L953.01,734.14 L987.52,721.43 L990.25,724.78 L993.21,723.62 L1002.27,731.54 Z', 'held', '["government"]', 'The creative merchants and ration team of the Garak Agricultural and Marine Products Wholesale Market want to allocate the remaining refrigeration power first to perishable goods. The market itself does not produce food.', '가락농수산물종합도매시장의 창작 상인과 배급조는 남은 냉장 전력을 부패하기 쉬운 물건에 우선 배정하려 한다. 시장 자체가 식량을 생산하지는 않는다.', 'Garak 1-dong residents negotiate the cost of the next choice: disclosing the refrigeration hours and stock.', '가락1동 주민들은 다음 선택의 비용을 협의한다: 냉장 가능한 시간과 재고를 공개한다.', 1, 1366951.5365969823, 5947.760240454708);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171063200', 397, 'Garak 2-dong', '가락2동', 'Songpa-gu', '송파구', 'M1068.65,745.85 L1055.95,759.38 L1045.53,749.88 L1044.69,749.65 L1035.04,755.77 L1026.75,743.27 L1036.28,724.12 L1040.58,718.04 L1047.84,724.15 L1052.06,726.98 L1060.15,733.16 L1072.43,740.99 L1068.65,745.85 Z', 'held', '["government"]', 'The creative handover team, which does not count the multiple source-data objects at Police Hospital Station as separate stations, records the actual entrances and the recipients of the luggage together.', '경찰병원역의 여러 원자료 객체를 별도 역 수로 세지 않는 창작 인계조는 실제 출입구와 짐 수령자를 함께 적는다.', 'Garak 2-dong residents negotiate the cost of the next choice: marking on-site zones on the handover chart.', '가락2동 주민들은 다음 선택의 비용을 협의한다: 현장 구획을 인계표에 표시한다.', 6, 940960.2393080126, 8886.241576104392);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171064100', 398, 'Munjeong 1-dong', '문정1동', 'Songpa-gu', '송파구', 'M1045.17,771.17 L1035.32,787.1 L1028.92,788.67 L1020.17,764.76 L1044.69,749.65 L1045.53,749.88 L1055.95,759.38 L1045.17,771.17 Z', 'held', '["government"]', 'The creative mending team at Munjeong High School repairs work clothes and shared bedding with the same materials and decides the priorities with residents. The storage choice for Munjeong 2-dong is distinguished by reducing the piling up of packaging materials, fuel, and daily goods in the same zone.', '문정고등학교의 창작 수선조는 작업복과 공동 침구를 같은 재료로 고치며 우선순위를 주민과 정한다. 문정2동의 보관 선택은 포장재·연료·생활품이 같은 구획에 쌓이는 일을 줄이는 것으로 구별된다.', 'Munjeong 1-dong residents negotiate the cost of the next choice: reserving time for repairing shared bedding.', '문정1동 주민들은 다음 선택의 비용을 협의한다: 공동 침구 수리 시간을 예약한다.', 0, 667295.1999935389, 8802.700813758102);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171064200', 399, 'Munjeong 2-dong', '문정2동', 'Songpa-gu', '송파구', 'M1028.92,788.67 L1032.25,795.81 L1037.04,811.82 L1035.67,837.34 L1033.34,836.06 L1031.31,837.14 L1027.71,846.5 L1023.3,850.38 L1023.68,848.06 L1023.01,842.09 L1021.11,837.4 L1015.68,827.07 L993.15,788.25 L991.27,786.46 L993.29,785.59 L994.83,784.31 L992.8,780.63 L988.91,772.26 L983.06,763.48 L1012.63,752.06 L1020.17,764.76 L1028.92,788.67 Z', 'held', '["government"]', 'The creative storage team at Garden Five Life wants to divide the zones so that daily goods and large shipping freight are not piled in the same corridor.', '가든파이브 라이프의 창작 보관조는 생활품과 큰 출하 화물을 같은 복도에 쌓지 않도록 구획을 나누려 한다.', 'Munjeong 2-dong residents negotiate the cost of the next choice: clearing the passage corridors and setting the storage zones.', '문정2동 주민들은 다음 선택의 비용을 협의한다: 통행 복도를 비우고 보관 구획을 정한다.', 1, 2355412.8263064646, 3635.0315767899247);
