INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174053000', 411, 'Myeongil 1-dong', '명일1동', 'Gangdong-gu', '강동구', 'M1102.98,541.09 L1099.75,560.67 L1096.97,559.9 L1091.34,563.96 L1091.69,565.74 L1083.02,563.16 L1083.63,562.78 L1084.69,559.09 L1086.59,542.59 L1077.19,542.06 L1076.35,541.24 L1076.18,540.63 L1084.46,528.82 L1088.14,528.26 L1104.58,528.6 L1102.98,541.09 Z', 'held', '["arc"]', 'The fictional care team at Gomyeong Elementary School looks after children in the classroom while guardians go out to carry rations. The fictional care team of Myeongil 1-dong checks with guardians the meals each household needs and the usable ingredients.', '고명초등학교의 창작 돌봄조는 보호자가 배급 운반을 나갈 때 교실에서 아이를 맡는다. 명일1동의 창작 돌봄조는 가구별 필요한 식사와 사용 가능한 식재료를 보호자와 함께 확인한다.', 'Residents of Myeongil 1-dong discuss the cost of the next choice: set up a rotating shift system for guardians.', '명일1동 주민들은 다음 선택의 비용을 협의한다: 보호자 순환 교대를 둔다.', 1, 620722.1541411908, 11972.98976751122);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174054000', 412, 'Myeongil 2-dong', '명일2동', 'Gangdong-gu', '강동구', 'M1133.61,575.85 L1131.74,572.98 L1130.09,571.45 L1123.38,569.4 L1114.2,569.82 L1100.15,562.94 L1099.75,560.67 L1102.98,541.09 L1104.58,528.6 L1122.83,526.21 L1120.88,559.15 L1129.67,561.62 L1131.61,561.67 L1139.71,560.36 L1141.65,563.56 L1133.61,575.85 Z', 'held', '["arc"]', 'The fictional repair team around Godeok Station inspects the condition of shared tools when they are returned, so that responsibility for damage is not passed on to the next user.', '고덕역 주변 창작 수리조는 공용 도구를 반납할 때 상태를 검사해 다음 사용자에게 손상 책임을 넘기지 않으려 한다.', 'Residents of Myeongil 2-dong discuss the cost of the next choice: carry out inspections when tools are returned.', '명일2동 주민들은 다음 선택의 비용을 협의한다: 공구 반납 검사를 실시한다.', 1, 936772.0678819815, 5394.268438666366);
