INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174066000', 423, 'Seongnae 3-dong', '성내3동', 'Gangdong-gu', '강동구', 'M1070.95,603.01 L1057.4,647.76 L1042.63,639.6 L1058.69,598.34 L1070.95,603.01 Z', 'held', '["arc"]', 'The fictional cooking team at Dunchon Station Traditional Market tries to organize the open-flame zone in an indoor space full of stalls and packaging materials.', '둔촌역 전통시장의 창작 취사조는 좌판과 포장재가 많은 실내에서 화기 구획을 정리하려 한다.', 'Residents of Seongnae 3-dong discuss the cost of the next choice: consolidate open-flame work into one zone.', '성내3동 주민들은 다음 선택의 비용을 협의한다: 화기 작업을 한 구획으로 모은다.', 1, 641575.0248053037, 10080.972216714215);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174068500', 424, 'Gil-dong', '길동', 'Gangdong-gu', '강동구', 'M1100.15,562.94 L1114.2,569.82 L1123.38,569.4 L1130.09,571.45 L1131.74,572.98 L1133.61,575.85 L1088.8,599.5 L1083.79,602.06 L1080.07,603.55 L1076.43,603.92 L1070.95,603.01 L1058.69,598.34 L1064.55,583.17 L1066.78,578.37 L1067.66,577.55 L1069.16,577.17 L1074.24,577.51 L1079.99,573.2 L1083.02,563.16 L1091.69,565.74 L1091.34,563.96 L1096.97,559.9 L1099.75,560.67 L1100.15,562.94 Z', 'held', '["arc"]', 'The fictional medical team in the Gangdong Seongsim Hospital building separates supplies for emergency preparedness from household support allotments in the same ledger.', '강동성심병원 건물의 창작 의무조는 응급 준비용 물자와 가구 지원분을 같은 장부에서 분리한다.', 'Residents of Gil-dong discuss the cost of the next choice: set aside the minimum emergency stock first.', '길동 주민들은 다음 선택의 비용을 협의한다: 응급 최소 재고를 먼저 남긴다.', 1, 1599869.6313770749, 8802.529733549763);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174069000', 425, 'Dunchon 1-dong', '둔촌1동', 'Gangdong-gu', '강동구', 'M1092.51,642.36 L1088.4,655.53 L1089.16,664.47 L1088.03,664.37 L1084,662.61 L1057.4,647.76 L1065.32,621.57 L1088.49,629.9 L1092.42,639.11 L1092.51,642.36 Z', 'held', '["arc"]', 'The fictional encampment team at Wirye Elementary School tries to keep the emergency passages clear by separating sleeping spaces from household belongings.', '위례초등학교의 창작 숙영조는 잠자리와 생활 짐을 분리해 비상 통로를 비워 두려 한다.', 'Residents of Dunchon 1-dong discuss the cost of the next choice: move the storage of household belongings to a separate zone.', '둔촌1동 주민들은 다음 선택의 비용을 협의한다: 생활 짐 보관을 별도 구획으로 옮긴다.', 1, 895456.9853427708, 11067.198271066572);
