INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('cheong-wa-dae', 0, 'Cheongwadae', '청와대', 'region:1111051500', 'government', 'Core Fortress · Government Center', '핵심 요새·정부 중심지', 'The office and residence of President Yun Seo-rin (K144) and the center of records, rations, and ratification; the core fortress of the Government. The Government Complex Seoul Main Building remains the forward administrative and defense post.', '대통령 윤서린(K144)의 집무·거처와 기록·배급·인준의 중심지이며 정부의 핵심 요새다. 정부서울청사 본관은 전방 행정·방어 거점으로 남는다', 606.26, 411.13, 'confirmed');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('government-complex-seoul', 1, 'Government Complex Seoul Main Building', '정부서울청사 본관', 'region:1111053000', 'government', 'Forward Administrative and Defense Post', '전방 행정·방어 거점', 'Handles security and passage for Gwanghwamun, Jongno 3-ga, and Euljiro-ipgu.', '광화문·종로3가·을지로입구 경비와 통행을 맡는다', 603.02, 453.53, 'confirmed');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('fki-hall', 2, 'Yeouido FKI Building', '여의도 전경련회관', 'region:1156054000', 'free-city', 'Meeting and Investment Ledger Support Post', '회의·출자 장부 보조 거점', 'Supports the meetings and ledgers of the Investment Federation, which holds the National Assembly Building as its core stronghold.', '국회의사당을 핵심 거점으로 둔 출자연합회의 회의와 장부를 보조한다', 445.88, 641.46, 'unknown');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('jogyesa', 3, 'Jogyesa', '조계사', 'region:1111061500', 'government', 'Ritual and Ratification Center', '의례·인준 중심지', 'Handles the rites and ratification of the Anguk Grand Monastery.', '안국총림의 의례와 인준을 맡는다', 622.75, 456.36, 'unknown');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('myeongdong-sanctuary', 4, 'Arc sanctuary', 'Arc 성소', 'region:1114055000', 'government', 'Ceremonial and Administrative Center', '예식·행정 중심지', 'Handles the ceremonies and administration of the Arc.', 'Arc의 예식과 행정을 맡는다', 637.56, 495.98, 'unknown');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('lotte-world-tower', 5, 'Lotte World Tower', '롯데월드타워', 'region:1171071000', 'government', 'Leader''s Residence · Above- and Below-Ground Core Fortress', '수장 거주·지상·지하 핵심 요새', 'The core fortress of the Government, where Lead Believer Nam Yun-gyeong (K373) resides. It uses the tower and the mall basement, with passage via the connecting passage to Jamsil Station. The ceremonial and administrative functions of the capital Myeongdong Station and Arc sanctuary are maintained.', '수석 신도 남윤경(K373)이 거주하는 정부의 핵심 요새다. 타워와 몰 지하를 사용하며 잠실역 연결 통로로 통행한다. 수도 명동역과 Arc 성소의 예식·행정 기능은 유지한다', 967.75, 679.75, 'confirmed');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('n-seoul-tower', 6, 'N Seoul Tower', 'N서울타워', 'region:1117052000', 'government', 'Observation and Manual Signal Relay Post', '관측·수동 신호 중계 거점', 'Observes all of Seoul and relays manual signals. The Central Intelligence Agency uses Namsan Tower as its base, and the organization is led by O Hae-rin, the current avatar of the Central Intelligence Agency AI.', '서울 전역을 관측하고 수동 신호를 중계한다. 중앙정보부는 남산타워를 거점으로 사용하며 중앙정보부 AI의 현재 아바타 오해린이 조직을 이끈다', 640.59, 538.8, 'unknown');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('national-assembly', 7, 'National Assembly Building', '국회의사당', 'region:1156054000', 'free-city', 'Leader''s Residence · Top-Priority Core Fortress', '수장 거주·최우선 핵심 요새', 'The top-priority core fortress of the Free City, where Speaker Choe Ji-u (K219) resides. The old plenary chamber is used as the meeting hall for representatives of the Investor States.', '의장 최지우(K219)가 거주하는 자유도시의 최우선 핵심 요새다. 옛 본회의장은 출자국 대표 회의장으로 쓴다', 427.63, 607.41, 'confirmed');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('ddp', 8, 'Dongdaemun Design Plaza', '동대문디자인플라자', 'region:1114059000', 'government', 'Above- and Below-Ground Passage and Goods Inspection Post', '지상·지하 통행·물자 검사 거점', 'Inspects passage and goods both above and below ground.', '지상과 지하의 통행 및 물자를 검사한다', 702.79, 482.26, 'unknown');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('city-hall', 9, 'Seoul City Hall', '서울시청', 'region:1114055000', 'government', 'Downtown Public Administration Post', '도심 공공업무 거점', 'The government uses it as its public administration counter in the city center.', '정부가 도심의 공공업무 창구로 사용한다', 612.61, 482.78, 'unknown');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('seoul-station', 10, 'Old Seoul Station Building', '서울역 옛 역사', 'region:1114054000', 'government', 'Railway Shift and Records Post', '철도 교대·기록 거점', 'Checks railway shifts and records at Seoul Station Plaza.', '서울역 광장의 철도 교대와 기록을 확인한다', 592.69, 521.54, 'unknown');
